insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-1-B', 1, 1, 'مدل خطی', '۲۰۰ × ۲٫۵ = ۵۰۰ و ۵۰۰ + ۱۰۰ = ۶۰۰. جمع‌بندی: این سؤال مفهوم «مدل خطی» را تثبیت کرد: ŷ = wx + b با جایگذاری کامل.', '["۵۰۰ فقط بخش ۲۰۰x است؛ b جا افتاده است.", "همین درست است: ۵۰۰ + ۱۰۰ = ۶۰۰.", "۴۵۰ از ضرب اشتباه ۲۰۰ در ۲٫۵ درمی‌آید.", "۷۰۰ یعنی b دو بار حساب شده است."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-1-B', 2, 1, 'تابع هزینه', 'خط درست هر دو مثال را دقیق می‌زند؛ خطا صفر است و هزینه صفر می‌شود. جمع‌بندی: این سؤال مفهوم «تابع هزینه» را تثبیت کرد: هزینه صفر فقط با خطای صفر می‌آید.', '["۱۲۵۰۰ هزینه خط غلط این درس بود، نه خط درست.", "همین درست است: خطای صفر یعنی J صفر.", "۲۵۰۰ از هیچ حساب این درس درنمی‌آید.", "۵۰۰۰۰ جمع مربع خطاهای خط غلط بود، پیش از تقسیم."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-1-B', 3, 2, 'تابع هزینه', 'جمع مربع خطاها ۵۰۰۰۰ بود و تقسیم بر ۲m یعنی ۴، می‌شود ۱۲۵۰۰. جمع‌بندی: این سؤال مفهوم «تابع هزینه» را تثبیت کرد: J میانگین مربع خطاها با ضریب یک‌دوم است.', '["۵۰۰۰۰ جمع مربع خطاهاست، پیش از تقسیم بر ۲m.", "۲۵۰۰۰ فقط تقسیم بر ۲ است؛ m هم باید در مخرج باشد.", "همین درست است: ۵۰۰۰۰ ÷ ۴ = ۱۲۵۰۰.", "۶۲۵۰ یک تقسیم اضافه دارد و از فرمول درنمی‌آید."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-1-B', 4, 1, 'گرادیان نزولی', 'قدم گرادیان نزولی جهت‌دار است، نه تصادفی؛ هر دو پارامتر با هم و از روی مقدار کهنه به‌روز می‌شوند. جمع‌بندی: این سؤال مفهوم «گرادیان نزولی» را تثبیت کرد: قدم جهت‌دار و به‌روزرسانی هم‌زمان پارامترها.', '["تکان تصادفی جهت ندارد و رسیدن به کف را تضمین نمی‌کند.", "همین درست است: شیب با مقدار کهنه، به‌روزرسانی هم‌زمان.", "b هم پارامتر است و مثل w در هر قدم تکان می‌خورد.", "مثال‌ها ثابت می‌مانند؛ چیزی که عوض می‌شود پارامترهاست."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-1-B', 5, 1, 'نرخ یادگیری', 'قدم‌های ریز یعنی هزاران قدم تا کف؛ جهت درست است، سرعت کم است. جمع‌بندی: این سؤال مفهوم «نرخ یادگیری» را تثبیت کرد: α کوچک یعنی رسیدن درست ولی دیر.', '["بیشتر شدن هزینه نشانه α بزرگ است، نه کوچک.", "همین درست است: α کوچک یعنی قدم ریز و راه طولانی.", "α کوچک به‌خودی‌خود خطا را صفر نمی‌کند؛ فقط آرام به کف می‌رسد.", "شکل هزینه به α ربطی ندارد؛ α فقط اندازه قدم است."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-1-B', 6, 1, 'همگرایی', 'همگرایی یعنی ایستادن روی کف: هزینه دیگر پایین نمی‌آید. جمع‌بندی: این سؤال مفهوم «همگرایی» را تثبیت کرد: همگرایی را از ثابت شدن J می‌شناسیم.', '["w صفر یعنی خط افقی؛ ربطی به کف هزینه ندارد.", "همین درست است: ثابت ماندن J نشانه رسیدن به کف است.", "شماره قدم ثابت برای همه مسئله‌ها وجود ندارد؛ نشانه، رفتار J است.", "نسبت b و w چیزی درباره کف هزینه نمی‌گوید."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-2-B', 1, 2, 'نرمال‌سازی میانگین', '(۳۰۰۰ − ۲۰۰۰) ÷ ۴۰۰۰ = ۱۰۰۰ ÷ ۴۰۰۰ = ۰٫۲۵. جمع‌بندی: این سؤال مفهوم «نرمال‌سازی میانگین» را تثبیت کرد: کم کردن میانگین و تقسیم بر دامنه.', '["۱ یعنی فقط بر خودش تقسیم شده است؛ میانگین کم نشده است.", "۰٫۵ جواب تقسیم ساده بر بیشینه بود، نه نرمال‌سازی میانگین.", "همین درست است: اول میانگین کم می‌شود، بعد تقسیم بر دامنه.", "۱۰۰۰ فقط صورت کسر است؛ تقسیم بر دامنه جا افتاده است."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-2-B', 2, 1, 'دلیل مقیاس‌بندی', 'ویژگی بزرگ و کوچک در یک مدل، کاسه را کشیده می‌کند؛ راه پایین رفتن پیچ‌درپیچ می‌شود. جمع‌بندی: این سؤال مفهوم «دلیل مقیاس‌بندی» را تثبیت کرد: هم‌اندازه کردن ویژگی‌ها کاسه را گرد و راه را کوتاه می‌کند.', '["هزینه صفر فقط با حدس دقیق می‌آید و ربطی به اندازه ویژگی ندارد.", "همین درست است: کاسه کشیده یعنی قدم زیگزاگی و همگرایی دیر.", "مقیاس‌بندی پارامتری کم یا زیاد نمی‌کند؛ فقط واحد ویژگی را عوض می‌کند.", "b در هر دو حالت سر جایش است."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-2-B', 3, 0, 'انتخاب نرخ یادگیری', 'هزینه صعودی نشانه پرش قدم از روی کف است؛ درمان اول، α کوچک‌تر است. جمع‌بندی: این سؤال مفهوم «انتخاب نرخ یادگیری» را تثبیت کرد: هزینه صعودی یعنی α را کوچک کن.', '["همین درست است: قدم کوچک‌تر از کف رد نمی‌شود و هزینه پایین می‌آید.", "α بزرگ‌تر پرش را بدتر می‌کند و هزینه بالاتر می‌رود.", "حذف مثال، مسئله را عوض می‌کند و قدم را درست نمی‌کند.", "چندجمله‌ای کردن مدل برای داده خمیده است، نه برای قدم‌های پرنده."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-2-B', 4, 1, 'مهندسی ویژگی', 'مساحت = جلو × عمق = ۱۲ × ۱۰ = ۱۲۰. جمع‌بندی: این سؤال مفهوم «مهندسی ویژگی» را تثبیت کرد: مساحت از ضرب دو ستون ساخته می‌شود.', '["۲۲ جمع جلو و عمق است؛ مساحت ضرب است، نه جمع.", "همین درست است: ۱۲ × ۱۰ = ۱۲۰.", "۱٫۲ یک رقم اعشار اضافه دارد و از ضرب درنمی‌آید.", "۱۰۰ فقط مربع عمق است و جلو در آن نیست."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-2-B', 5, 1, 'رگرسیون چندجمله‌ای', 'الگوی خمیده، ویژگی خمیده می‌خواهد؛ x² به مدل اجازه خم گرفتن می‌دهد. جمع‌بندی: این سؤال مفهوم «رگرسیون چندجمله‌ای» را تثبیت کرد: برای داده خمیده، ویژگی خمیده بساز.', '["خط راست روی الگوی خمیده همیشه زیر یا روی داده می‌ایستد.", "همین درست است: ویژگی خمیده برای الگوی خمیده.", "حذف مثال یعنی دور ریختن اطلاعات، نه حل مسئله.", "α اندازه قدم است؛ شکل مدل را خم نمی‌کند."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-2-B', 6, 1, 'بیش‌برازش (پیش‌نمایش)', 'مدل مثال‌ها را حفظ کرده و الگو را یاد نگرفته است؛ درس ۳-ب (فاز ۱) این دام را کامل باز می‌کند. جمع‌بندی: این سؤال مفهوم «بیش‌برازش» را تثبیت کرد: حفظ کردن مثال‌ها با یاد گرفتن الگو فرق دارد.', '["کم‌برازش برعکس است: مدل حتی روی آموزش هم بد است.", "همین درست است: خطای آموزش صفر با خطای تازه بالا یعنی بیش‌برازش.", "همگرایی فقط یعنی هزینه دیگر کم نمی‌شود؛ خوب و بدش را نمی‌گوید.", "مقیاس‌بندی یک درمان است، نه اسم این دام."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-3-B', 1, 2, 'هزینه لگاریتمی', 'log(۰٫۹)- حدود ۰٫۱۰۵ است؛ حدس نزدیک و درست، جریمه کمی دارد. جمع‌بندی: این سؤال مفهوم «هزینه لگاریتمی» را تثبیت کرد: حدس نزدیک، جریمه کم.', '["۲٫۳۰۳ هزینه حدس ۰٫۱ بود؛ حدس مطمئنِ غلط.", "۰٫۶۹ هزینه حدس ۰٫۵ است؛ حدس مردد.", "همین درست است: حدس ۰٫۹ نزدیک جواب واقعی است و جریمه‌اش کم است.", "هزینه صفر فقط با حدس دقیق ۱ می‌آید، نه ۰٫۹."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-3-B', 2, 1, 'هزینه لگاریتمی', 'هزینه مربعی روی خروجی سیگموید شکل غیرمحدب می‌سازد؛ هزینه لگاریتمی کاسه صاف می‌دهد. جمع‌بندی: این سؤال مفهوم «هزینه لگاریتمی» را تثبیت کرد: برای لجستیک، هزینه باید کاسه صاف بسازد.', '["سرعت حساب مسئله نیست؛ شکل هزینه مسئله است.", "همین درست است: کاسه موج‌دار یعنی گیر کردن در کمینه‌های الکی.", "مربع خطا به خانه اختصاص ندارد؛ برای طبقه‌بندی شکلش خراب می‌شود.", "لجستیک w و b دارد؛ پارامترش همان‌های مدل خطی‌اند."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-3-B', 3, 1, 'بیش‌برازش', 'رد شدن از همه نقطه‌های آموزش با شکست روی داده تازه، تعریف عملی بیش‌برازش است. جمع‌بندی: این سؤال مفهوم «بیش‌برازش» را تثبیت کرد: پیچیدگی بی‌حساب، حفظ کردن می‌آورد.', '["کم‌برازش یعنی مدل حتی روی آموزش هم بد باشد؛ این‌جا آموزش عالی است.", "همین درست است: خم پیچیده مثال‌ها را حفظ کرده است.", "همگرایی فقط ایستادن هزینه است و تشخیص کیفیت نیست.", "مقیاس‌بندی نام یک درمان است، نه این تشخیص."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-3-B', 4, 0, 'کم‌برازش', 'کم‌برازش یعنی مدل از مسئله ساده‌تر است؛ حتی آموزش را هم نمی‌گیرد. جمع‌بندی: این سؤال مفهوم «کم‌برازش» را تثبیت کرد: سادگی بیش از حد، خطای آموزش را هم بالا نگه می‌دارد.', '["همین درست است: خط راست روی خم، از اول روی آموزش هم بد است.", "خطای آموزش صفر با پیچیدگی زیاد، سمت بیش‌برازش است.", "خطای متعادل نشانه سلامت است، نه کم‌برازش.", "خطا فقط روی داده تازه با آموزش خوب، باز هم بیش‌برازش است."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-3-B', 5, 2, 'جریمه منظم‌سازی', '(۱۰ ÷ (۲ × ۲)) × ۳² = ۲٫۵ × ۹ = ۲۲٫۵. جمع‌بندی: این سؤال مفهوم «جریمه منظم‌سازی» را تثبیت کرد: جریمه = (λ ÷ ۲m) × جمع مربع وزن‌ها.', '["۱۵ یعنی ۹ با چیزی غیر از ضریب فرمول ضرب شده است.", "۴۵ یعنی تقسیم بر ۲m جا افتاده و فقط بر ۲ تقسیم شده است.", "همین درست است: (λ ÷ ۲m) × w² = ۲۲٫۵.", "۹ فقط مربع وزن است؛ ضریب λ در آن نیست."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-3-B', 6, 1, 'بیش‌برازش و درمانش', 'خطای آموزش نزدیک صفر همراه با خطای بالای داده تازه یعنی مدل مثال‌های آموزش را حفظ کرده است: بیش‌برازش. درمان این درس جریمه منظم‌سازی و داده بیشتر است تا مدل ساده‌تر و کلی‌تر شود. جمع‌بندی: این سؤال مفهوم «بیش‌برازش» را تثبیت کرد: حفظ کردن آموزش، و درمانش منظم‌سازی و داده بیشتر.', '["کم‌برازش یعنی خطای آموزش هم بالا بماند؛ این‌جا خطای آموزش نزدیک صفر است.", "همین درست است: بیش‌برازش با منظم‌سازی و داده بیشتر درمان می‌شود.", "نشت داده تعریف دیگری دارد و درمان این دام در این درس نیست.", "کم کردن λ جریمه را کمتر و حفظ کردن را بیشتر می‌کند؛ یعنی برعکس درمان."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-4-B', 1, 1, 'فعال‌سازی لایه پنهان', 'z این نورون ۲ است و g(۲) ≈ ۰٫۸۸؛ همان عدد جدول گام ۲. جمع‌بندی: این سؤال مفهوم «فعال‌سازی لایه پنهان» را تثبیت کرد: اول z، بعد g(z).', '["۰٫۵۰ فعال‌سازی نورون دوم است که z اش صفر بود.", "همین درست است: z = ۲ و سیگموید ۲ تقریباً ۰٫۸۸ است.", "۲ خود z است، پیش از فعال‌ساز؛ فعال‌سازی باید روی آن بنشیند.", "۰٫۵۹ حدس نهایی لایه خروجی است، نه این نورون."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-4-B', 2, 1, 'z لایه خروجی', 'z = ۰٫۸۸ + ۰٫۵۰ − ۱ = ۰٫۳۸؛ بایاس ۱- باید کم شود. جمع‌بندی: این سؤال مفهوم «z لایه خروجی» را تثبیت کرد: ورودی لایه خروجی، فعال‌سازی لایه پنهان است.', '["۱٫۳۸ جمع دو فعال‌سازی است بدون بایاس؛ بایاس جا افتاده است.", "همین درست است: ۱٫۳۸ − ۱ = ۰٫۳۸.", "۰٫۵۹ فعال‌سازی بعد از z است؛ سؤال z را می‌پرسد.", "۱٫۸۸ یعنی بایاس به‌جای کم شدن، اضافه شده است."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-4-B', 3, 1, 'تفسیر حدس', 'لایه خروجی سیگمویدی عددی بین صفر و یک می‌سازد و در مسئله دودویی، آن عدد احتمال کلاس یک است. جمع‌بندی: این سؤال مفهوم «تفسیر حدس» را تثبیت کرد: خروجی سیگمویدی در مسئله دودویی، احتمال است.', '["خروجی سیگموید احتمال است، نه قیمت؛ قیمت ورودی مسئله بود.", "همین درست است: ۰٫۵۹ یعنی احتمال حدود ۵۹ درصد برای پرفروش شدن.", "درصد درستی روی مثال‌ها تعریف دیگری است و از یک حدس تنها درنمی‌آید.", "z لایه خروجی ۰٫۳۸ بود؛ ۰٫۵۹ فعال‌سازی بعد از آن است."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-4-B', 4, 1, 'نقش کتابخانه', 'کتابخانه ماشین حساب شبکه است: لایه را تعریف می‌کنی و حساب و وزن‌ها با اوست؛ فهم کار همچنان با توست. جمع‌بندی: این سؤال مفهوم «نقش کتابخانه» را تثبیت کرد: تنسورفلو حساب را آماده می‌کند، فهم را نه.', '["مسئله و داده کار آدم است؛ کتابخانه فقط حساب شبکه را انجام می‌دهد.", "همین درست است: Dense و دوستانش حساب لایه‌ها را آماده کرده‌اند.", "جواب درست را داده آموزشی می‌گوید، نه کتابخانه.", "درس ۴-الف (فاز ۲) و همین درس برای همین‌اند: اول فهم با دست، بعد سرعت با کتابخانه."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-4-B', 5, 1, 'شکل داده', 'قرارداد دوره این است: سطر = مثال، ستون = سرنخ؛ پس ۲۰۰ سطر و ۳ ستون. جمع‌بندی: این سؤال مفهوم «شکل داده» را تثبیت کرد: هر سطر یک مثال و هر ستون یک سرنخ.', '["این شکل جابه‌جای درست است؛ سطر باید مثال باشد، نه سرنخ.", "همین درست است: ۲۰۰ مثال در سطرها و ۳ سرنخ در ستون‌ها.", "چیدن همه عددها در یک سطر، مرز مثال‌ها را از بین می‌برد.", "داده ورودی سرنخ‌هاست؛ جواب‌ها جدول جدا خودشان را دارند."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-4-B', 6, 1, 'حدس برای ورودی تازه', 'زنجیره گام‌های ۲ و ۳ با ورودی تازه: فعال‌سازی‌های پنهان [۰٫۷۳, ۰٫۵۰] می‌شوند، z خروجی ۰٫۲۳ و فعال‌سازی‌اش تقریباً ۰٫۵۶ است؛ همان مثال‌های کارشده آن دو گام. جمع‌بندی: این سؤال مفهوم «حدس برای ورودی تازه» را تثبیت کرد: همان شبکه با ورودی تازه، زنجیره کامل را دوباره می‌رود.', '["۰٫۵۹ حدس ورودی [۲, ۱] بود؛ ورودی عوض شده است.", "همین درست است: ۰٫۷۳ + ۰٫۵۰ − ۱ = ۰٫۲۳ و g(۰٫۲۳) ≈ ۰٫۵۶.", "۰٫۲۳ خود z خروجی است، پیش از فعال‌ساز.", "۰٫۷۳ فعال‌سازی نورون نخست لایه پنهان است، نه حدس نهایی."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-5-B', 1, 1, 'احتمال سافت‌مکس', 'عدد توانی دسته نخست ۷٫۳۹ از جمع ۱۱٫۱۱ است و ۷٫۳۹ ÷ ۱۱٫۱۱ ≈ ۰٫۶۷ می‌شود. جمع‌بندی: این سؤال مفهوم «احتمال سافت‌مکس» را تثبیت کرد: سهم هر دسته از جمع عددهای توانی.', '["۰٫۲۴ سهم دسته دوم است.", "همین درست است: بزرگ‌ترین z بزرگ‌ترین سهم را می‌گیرد.", "۰٫۰۹ سهم دسته سوم با z صفر است.", "۲ خود z است؛ احتمال باید بین صفر و یک باشد."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-5-B', 2, 1, 'احتمال سافت‌مکس با نمره تازه', 'عددهای توانی [۲۰٫۰۹, ۲٫۷۲, ۱٫۰۰] و جمعشان ۲۳٫۸۰ است؛ سهم دسته نخست ۲۰٫۰۹ ÷ ۲۳٫۸۰ ≈ ۰٫۸۴ می‌شود. جمع‌بندی: این سؤال مفهوم «احتمال سافت‌مکس» را تثبیت کرد: با z بزرگ‌تر، سهم دسته نخست از ۰٫۶۷ به ۰٫۸۴ رسید.', '["۰٫۶۷ سهم دسته نخست در مثال z = [۲, ۱, ۰] بود؛ این‌جا نمره دسته نخست بزرگ‌تر شده است.", "همین درست است: نمره بزرگ‌تر، سهم بزرگ‌تر؛ تقریباً ۰٫۸۴.", "۰٫۱۱ سهم دسته دوم همین مثال است.", "۳ خود نمره خام است؛ احتمال باید میان صفر و یک باشد."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-5-B', 3, 1, 'هزینه حدس مطمئن غلط', 'هزینه = log(۰٫۰۹)− ≈ ۲٫۴۱؛ اطمینان روی دسته غلط، با احتمال کم برای جواب درست، گران تمام می‌شود. جمع‌بندی: این سؤال مفهوم «هزینه حدس مطمئن غلط» را تثبیت کرد: یقین اشتباه، گران‌ترین خطاست.', '["احتمال، هزینه نیست؛ لگاریتم منفی‌اش هزینه است.", "همین درست است: احتمال کوچکِ جواب درست یعنی هزینه بزرگ.", "یک منهای احتمال، تعریف هزینه این درس نیست.", "اطمینان به‌خودی‌خود خوب نیست؛ اطمینان روی جواب غلط بدترین حالت است."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-5-B', 4, 1, 'چرخه آموزش', 'اول حدس ساخته می‌شود، بعد بد بودنش سنجیده می‌شود، بعد سهم وزن‌ها حساب و در پایان وزن‌ها تکان داده می‌شوند. جمع‌بندی: این سؤال مفهوم «چرخه آموزش» را تثبیت کرد: جلو، هزینه، عقب، به‌روزرسانی.', '["به‌روزرسانی بدون دانستن هزینه و گرادیان، تکان کور است.", "همین درست است: حدس، سنجش، سهم وزن‌ها، حرکت.", "رو به عقب پیش از رو به جلو چیزی برای برگرداندن ندارد.", "هزینه پیش از حدس ساخته نمی‌شود؛ اول باید حدسی باشد که سنجیده شود."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-5-B', 5, 1, 'Adam', 'Adam همان قدم به‌روزرسانی را هوشمندتر می‌کند: قدم per-weight و حافظه جهت حرکت. جمع‌بندی: این سؤال مفهوم «Adam» را تثبیت کرد: بهینه‌ساز، قدم‌های به‌روزرسانی را هوشمند می‌کند.', '["هیچ بهینه‌سازی هزینه صفر را تضمین نمی‌کند؛ فقط بهتر به سویش حرکت می‌کند.", "همین درست است: قدم جدا برای هر وزن، با توجه به رفتار اخیر گرادیان.", "بدون داده، هزینه‌ای نیست که کم شود؛ Adam هم با همان داده کار می‌کند.", "معماری شبکه تصمیم برنامه‌نویس است؛ Adam فقط آموزش همان شبکه را پیش می‌برد."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-5-B', 6, 1, 'سیگموید یا سافت‌مکس', 'ده دسته ناسازگار داریم؛ برای هر دسته یک نورون و احتمال‌ها با سافت‌مکس روی هم جمع یک می‌شوند. جمع‌بندی: این سؤال مفهوم «سیگموید یا سافت‌مکس» را تثبیت کرد: چند دسته ناسازگار یعنی چند نورون با سافت‌مکس.', '["یک سیگموید فقط احتمال یک کلاس در برابر بقیه را می‌دهد؛ برای ده دسته کافی نیست.", "همین درست است: هر دسته یک نورون و سافت‌مکس روی همه با هم.", "خروجی خطی یک عدد آزاد می‌دهد؛ رقم یک دسته است، نه یک عدد پیوسته.", "ReLU احتمال نمی‌سازد و جمع خروجی‌هایش یک نمی‌شود."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-6-B', 1, 1, 'قدم بعدی در چرخه', 'شکاف ۱۱ درصدی یعنی بیش‌برازش؛ درمان‌هایش داده و منظم‌سازی‌اند، نه بزرگ‌تر کردن مدل. جمع‌بندی: این سؤال مفهوم «قدم بعدی در چرخه» را تثبیت کرد: اول تشخیص سوگیری/واریانس، بعد درمان همان.', '["مدل بزرگ‌تر بیش‌برازش را بدتر می‌کند؛ این درمان سوگیری بالاست.", "همین درست است: درمان باید با تشخیص جور شود.", "آموزش طولانی‌تر معمولاً حفظ کردن را بیشتر می‌کند، نه کمتر.", "اعتبارسنجی آینه تشخیص است؛ کنار گذاشتنش یعنی از دست دادن آینه."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-6-B', 2, 1, 'تحلیل خطا', 'تحلیل خطا یعنی شمردن دسته‌ها و سهمشان؛ اولویت تعمیر از عدد می‌آید، نه از چشم. جمع‌بندی: این سؤال مفهوم «تحلیل خطا» را تثبیت کرد: تصمیم تعمیر از جدول دسته‌ها و سهم‌ها می‌آید.', '["به چشم آمدن با بزرگ بودن فرق دارد؛ دسته پر سر و صدا ممکن است سهم کوچکی داشته باشد.", "همین درست است: نمونه خطا، دسته‌بندی، شمارش سهم.", "داده بیشتر یک درمان خاص است و بدون تشخیص ممکن است بی‌ربط باشد.", "عوض کردن سنجه برای کم دیدن خطا، خودفریبی است؛ خطا سر جایش می‌ماند."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-6-B', 3, 0, 'دقت کلی گمراه‌کننده', 'دقت کلی (۶ + ۹۸۸) ÷ ۱۰۰۰ = ۹۹٫۴ درصد است؛ ولی کار اصلی مدل پیدا کردن بیماران بود و ۴ بیمار از دست رفته‌اند. جمع‌بندی: این سؤال مفهوم «دقت کلی گمراه‌کننده» را تثبیت کرد: چهار خانه مثال را با هم بخوان، نه یک درصد تنها را.', '["همین درست است: دقت کلی از سالم‌های فراوان باد کرده است و فراخوانی واقعیت را می‌گوید.", "۶۰ درصد فراخوانی است؛ مخرجش بیماران واقعی است، نه همه آدم‌ها.", "۷۵ درصد دقتِ اعلام است؛ مخرجش اعلام‌های مدل است.", "دقتش کامل نیست؛ ۴ بیمار از دست رفته‌اند و بالا بودن عدد از فراوانی سالم‌ها آمده است."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-6-B', 4, 1, 'F1', 'F1 = ۲×۰٫۷۵×۰٫۶۰ ÷ (۰٫۷۵+۰٫۶۰) = ۰٫۹۰ ÷ ۱٫۳۵ ≈ ۰٫۶۷؛ میانگین هماهنگ دو عدد و از هر دو کمتر است. جمع‌بندی: این سؤال مفهوم «F1» را تثبیت کرد: میانگین هماهنگ دقتِ اعلام و فراخوانی.', '["۰٫۶۸ میانگین ساده دو عدد است؛ F1 میانگین هماهنگ است و کمی پایین‌تر می‌نشیند.", "همین درست است: ۰٫۹۰ تقسیم بر ۱٫۳۵.", "۰٫۷۵ خود دقتِ اعلام است، نه ترکیب دو سنجه.", "۱٫۳۵ جمع دو عدد و مخرج فرمول است، نه جواب."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-6-B', 5, 1, 'افزایش داده', 'مثال‌های ساخته‌شده تنوع آموزش را بالا می‌برند و حفظ کردن را سخت‌تر می‌کنند؛ درمان طبیعی بیش‌برازش‌اند. جمع‌بندی: این سؤال مفهوم «افزایش داده» را تثبیت کرد: مثال تازه از دل مثال موجود، علیه بیش‌برازش.', '["خریدن داده راه دیگری برای داده بیشتر است و درمان سوگیری، مدل قوی‌تر است نه داده متنوع‌تر.", "همین درست است: تنوع مصنوعی مثال‌ها علیه حفظ کردن کار می‌کند.", "حذف مثال سخت مسئله را پنهان می‌کند و درمانی نیست.", "فونت و شکل نمایش داده اثری روی یادگیری مدل ندارد."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-6-B', 6, 1, 'موازنه دقت و فراخوانی', 'هزینه دو خطا برابر نیست: بیمارِ ازدست‌رفته ممکن است درمان نشود، ولی اعلام غلط با یک آزمایش دیگر روشن می‌شود. جمع‌بندی: این سؤال مفهوم «موازنه دقت و فراخوانی» را تثبیت کرد: سنجه مهم‌تر را هزینه واقعی هر خطا انتخاب می‌کند.', '["اعلام غلط هزینه دارد، ولی در غربالگری بیماری خطرناک، هزینه‌اش از بیماریِ پیدا نشده کمتر است.", "همین درست است: اول همه بیماران را پیدا کن، بعد اعلام‌های غلط را پالایش کن.", "دقت کلی روی داده نامتوازن فریبنده است؛ گام ۴ همین را نشان داد.", "خطای آموزش درباره رفتار مدل روی داده تازه چیزی نمی‌گوید."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-7-B', 1, 1, 'دلیل تفاوت درخت‌ها', 'سود گروه از تفاوت اعضاست؛ صد کپی از یک درخت، یک درخت است با صد اسم. جمع‌بندی: این سؤال مفهوم «دلیل تفاوت درخت‌ها» را تثبیت کرد: رأی‌گیری فقط با درخت‌های متفاوت معنا دارد.', '["دقت گروه از کم شدن خطاهای متفاوت هم می‌آید؛ کپی یکسان خطای یکسان دارد.", "همین درست است: تنوع نمونه و سرنخ، شرط کار کردن جنگل است.", "مساوی شدن ربطی ندارد؛ همه یک جواب می‌دهند و همان برنده است.", "XGBoost ساخت ترتیبی می‌خواهد، نه کپی موازی."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-7-B', 2, 1, 'خواندن نمونه با جایگذاری', 'اندیس‌های حاضر ۷ تایند و اندیس‌های ۴ و ۶ و ۸ غایب‌اند؛ تکرار اندیس‌های ۲ و ۷ امضای نمونه‌گیری با جایگذاری است. جمع‌بندی: این سؤال مفهوم «نمونه‌گیری با جایگذاری» را تثبیت کرد: نمونه ده‌تایی می‌تواند ۷ یکتا و ۳ غایب داشته باشد.', '["اگر هر مثال دقیقاً یک بار می‌آمد، نمونه‌گیری با جایگذاری نبود.", "همین درست است: ۷ حاضر و ۳ غایب، با دو اندیس تکراری.", "۳ تعداد غایب‌هاست، نه یکتاها؛ جای دو عدد عوض شده است.", "غایب‌ها صفر نیستند؛ سه اندیس اصلاً در نمونه نیامده‌اند."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-7-B', 3, 1, 'انتخاب مدل برای داده جدولی', 'داده ساخت‌یافته جدولی با سرنخ آماده، خانه طبیعی درخت‌هاست؛ سریع‌اند و به مقیاس‌بندی هم نیاز ندارند. جمع‌بندی: این سؤال مفهوم «انتخاب مدل برای داده جدولی» را تثبیت کرد: داده ساخت‌یافته، اول درخت‌ها را صدا می‌زند.', '["کانولوشن برای داده شبکه‌ای مثل عکس است، نه جدول وام.", "همین درست است: جدول آماده یعنی قلمرو درخت و گروه درخت‌ها.", "شبکه بازگشتی برای دنباله‌هاست؛ سطرهای جدول ترتیب زمانیِ مدل‌خواستنی ندارند.", "مدل خطی یک نامزد است، ولی انتخاب اولِ معمول برای جدول، درخت و تقویت است و «بدون بررسی» هیچ‌وقت قاعده نیست."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-7-B', 4, 1, 'مقیاس‌بندی و درخت', 'برش «درآمد از ۵۰ بیشتر است؟» با ضرب همه درآمدها در هزار هم همان برش می‌ماند؛ آستانه فقط جابه‌جا می‌شود. جمع‌بندی: این سؤال مفهوم «مقیاس‌بندی و درخت» را تثبیت کرد: پرسش آستانه‌ای به مقیاس سرنخ حساس نیست.', '["درخت عددها را می‌خواند؛ با مقایسه و آستانه می‌خواند.", "همین درست است: مقیاس، ترتیب را عوض نمی‌کند و پرسش‌ها روی ترتیب سوارند.", "دقت به مسئله بستگی دارد؛ این جمله دلیل مقیاس نیست و همیشه هم درست نیست.", "داده جدولی معمولاً ناهم‌اندازه است؛ نکته این است که درخت به آن حساس نیست."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-7-B', 5, 1, 'تقویت در برابر جنگل', 'تقویت ترتیبی خطا را هدف می‌گیرد و قوی است، ولی همین تمرکز، حساسیتش به تنظیم و بیش‌برازش را بالا می‌برد. جمع‌بندی: این سؤال مفهوم «تقویت در برابر جنگل» را تثبیت کرد: تعمیر ترتیبی خطا در برابر رأی موازی.', '["دو روش جدا هستند: یکی موازی و رأی‌گیری، یکی ترتیبی و تعمیر خطا.", "همین درست است: قدرت بیشتر با حساسیت بیشتر، بهای تقویت است.", "«همیشه بهتر» در یادگیری ماشین جمله درستی نیست؛ به داده و تنظیم بستگی دارد.", "XGBoost هم طبقه‌بندی می‌کند و هم احتمال می‌دهد؛ ادعای سؤال نادرست است."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-7-B', 6, 1, 'رأی جنگل و تنوع درخت‌ها', 'جنگل موازی است: هر درخت روی نمونه‌گیری با جایگذاری و زیرمجموعه تصادفی سرنخ‌ها ساخته می‌شود؛ همین تنوع، با رأی اکثریت، واریانس جواب را کم می‌کند. تعمیر ترتیبی خطا کار تقویت (بوستینگ) است، نه جنگل. جمع‌بندی: این سؤال مفهوم «جنگل تصادفی» را تثبیت کرد: درخت‌های متنوع و رأی اکثریت، در برابر لرزش یک درخت تنها.', '["اگر درخت‌ها کپی هم باشند، رأی چیزی اضافه نمی‌کند؛ تنوع شرط کار جنگل است.", "همین درست است: تنوع درخت‌ها به‌علاوه رأی اکثریت، جواب آرام‌تر می‌سازد.", "جنگل هم می‌تواند بیش‌برازش کند؛ «همیشه» در این درس جایی ندارد.", "ساختن ترتیبی و تعمیر خطا تعریف تقویت است، نه جنگل تصادفی."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-8-B', 1, 1, 'K-means — جابه‌جایی مرکز', 'مرکز، میانگین نقطه‌های گروه است: (۴ + ۶ + ۸) ÷ ۳ = ۶. جمع‌بندی: این سؤال مفهوم «جابه‌جایی مرکز» را تثبیت کرد: مرکز تازه یعنی میانگین گروه.', '["۴ کوچک‌ترین نقطه گروه است، نه میانگینش.", "همین درست است: میانگین سه نقطه ۶ می‌شود.", "۸ بزرگ‌ترین نقطه است؛ مرکز نماینده میانگین است، نه افراطی‌ترین عضو.", "۱۸ جمع نقطه‌هاست؛ تقسیم بر تعداد نقطه‌ها جا افتاده است."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-8-B', 2, 1, 'شکل تپه گاوسی', 'σ انحراف معیار است: پخشی بیشتر یعنی تپه پهن‌تر می‌شود و چون مساحتش ثابت است، قله‌اش کوتاه‌تر می‌شود. جمع‌بندی: این سؤال مفهوم «σ در تپه گاوسی» را تثبیت کرد: σ یعنی پهنا و پخشی.', '["قله بلند و تپه باریک مال σ کوچک است، یعنی داده فشرده نزدیک میانگین.", "همین درست است: σ بزرگ یعنی پراکندگی زیاد و تپه پهن.", "جای قله را μ تعیین می‌کند، نه σ.", "تعداد ناهنجار به آستانه و داده بستگی دارد؛ σ فقط شکل پخش عادی را می‌گوید."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-8-B', 3, 1, 'قانون آستانه', 'قانون یک مقایسه است: ۰٫۰۲۷ > ۰٫۰۱، پس نقطه بالای خط ε مانده و عادی است؛ با ε = ۰٫۰۵ حکم همین نقطه برعکس و ناهنجار می‌شد. جمع‌بندی: این سؤال مفهوم «قانون آستانه» را تثبیت کرد: حکم با مقایسه p(x) و ε ساخته می‌شود، نه با دوری خام.', '["مقایسه با صفر قانون نیست؛ هر احتمالی از صفر بزرگ‌تر است.", "همین درست است: p(x) بالای خط ε یعنی عادی؛ جهت مقایسه را با گام ۳ بسنج.", "دوری از میانگین به‌تنهایی حکم نیست؛ آن دوری اول به p(x) تبدیل و بعد با ε سنجیده می‌شود.", "خوشه‌بندی ابزار نیمه دیگر هفته است؛ این تصمیم مال الگوریتم ناهنجاری است."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-8-B', 4, 2, 'چند ویژگی', 'هر ویژگی تپه خودش را دارد و احتمال مشترک، حاصل‌ضرب احتمال‌هاست؛ یک ویژگی خیلی عجیب حاصل‌ضرب را کوچک می‌کند. جمع‌بندی: این سؤال مفهوم «احتمال چند ویژگی» را تثبیت کرد: ضرب احتمال‌های هر ویژگی.', '["جمع کردن احتمال‌ها می‌تواند از یک هم بگذرد و معنا ندارد.", "کنار گذاشتن یک ویژگی یعنی نیمی از سرنخ‌ها را ندیدن.", "همین درست است: ضرب احتمال‌های جدا برای هر ویژگی.", "میانگین گرفتن اثر ویژگی عجیب را رقیق می‌کند و نقطه مشکوک را پنهان می‌کند."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-8-B', 5, 1, 'ناهنجاری در برابر نظارت‌شده', 'وقتی کلاس ناهنجار کم‌نمونه و ناشناخته‌شکل است، یاد گرفتن «عادی» و گرفتن هر ناعادی‌ای، راه دوره اصلی است. جمع‌بندی: این سؤال مفهوم «انتخاب راه» را تثبیت کرد: ناهنجار کم و ناشناخته یعنی تشخیص ناهنجاری.', '["نظارت‌شده به مثال برچسب‌دار فراوان از هر دو کلاس نیاز دارد که این‌جا نیست.", "همین درست است: تپه عادی ساخته می‌شود و هر تراکنش نامحتمل گرفته می‌شود.", "دو خوشه ساختن، تقلب را تضمین نمی‌کند؛ خوشه‌ها فقط شباهت‌اند، نه برچسب تقلب.", "رگرسیون خطی عدد پیوسته حدس می‌زند، نه پرچم ناهنجاری."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-8-B', 6, 1, 'ویژگی خوب برای ناهنجاری', 'تپه گاوسی روی ویژگی تپه‌ای‌شکل سوار می‌شود و پرش هنگام خرابی دقیقاً همان چیزی است که باید دیده شود. جمع‌بندی: این سؤال مفهوم «ویژگی خوب» را تثبیت کرد: در حالت عادی تپه‌ای و هنگام خرابی پرشی.', '["ویژگی بی‌ربط به خرابی، هنگام خرابی هم عوض نمی‌شود و چیزی را لو نمی‌دهد.", "همین درست است: عادیِ تپه‌ای + تغییر ناگهانی هنگام خرابی.", "شماره سریال شناسه است، نه اندازه؛ از فاز ۱ می‌دانی شناسه الگوی یادگرفتنی ندارد.", "ویژگی بی‌الگو در حالت عادی، تپه‌ای نمی‌سازد تا ناهنجاری‌اش سنجیده شود."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-9-B', 1, 1, 'انتخاب با ضرب داخلی', 'ضرب‌های داخلی: ۰٫۲ و ۰٫۸ و ۰٫۵؛ فیلم دوم با ۰٫۲ × ۰ + ۰٫۸ × ۱ = ۰٫۸ بالاترین است، چون این کاربر عاشقانه‌دوست است. جمع‌بندی: این سؤال مفهوم «انتخاب با ضرب داخلی» را تثبیت کرد: بیشترین ضرب داخلی برنده است و برنده با نمایه عوض می‌شود.', '["حسابش درست است (۰٫۲) ولی کمترین همانندی است؛ این فیلم مال کاربر اکشن‌دوست بود.", "همین درست است: همانندی ۰٫۸ از همه بیشتر است.", "حسابش درست است (۰٫۵) ولی وسط می‌ایستد.", "هر سه همانندی جدا حساب شدند و برابر نیستند."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-9-B', 2, 1, 'فرق دو راه', 'منبع حدس دو راه فرق دارد: جمع کاربرها در برابر محتوای خود قلم و نمایه. جمع‌بندی: این سؤال مفهوم «فرق دو راه» را تثبیت کرد: جمع در برابر محتوا.', '["سرعت و دقت، فرق تعریف‌کننده این دو راه نیست.", "همین درست است: منبع یادگیری دو راه متفاوت است.", "هر دو راه برای هر جنس قلمی به کار می‌روند، نه فقط فیلم یا کالا.", "برچسب دودویی رفتار هم برای راه مشارکتی کافی است؛ ستاره اجباری نیست."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-9-B', 3, 1, 'سلیقه غیرمنتظره', 'محتوامحور به جنس همیشگی می‌چسبد؛ غافلگیری از الگوی جمع می‌آید و آن کار پالایش مشارکتی است. جمع‌بندی: این سؤال مفهوم «غافلگیری مشارکتی» را تثبیت کرد: جمع، بیرون از جنس همیشگی را هم می‌آورد.', '["مستند طبیعت هم‌جنس اکشن نیست و محتوامحور دقیقاً دنبال هم‌جنس می‌گردد.", "همین درست است: پیشنهاد غیرمنتظره امضای راه مشارکتی است.", "پیشنهاد هم‌جنس تنها یک راه از دو راه است؛ راه دیگر غافلگیر می‌کند.", "بازیابی مرحله بیرون کشیدن نامزدهاست، نه یک راه یادگیری سلیقه."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-9-B', 4, 1, 'نمایه کاربر', 'نمایه باید با ویژگی فیلم قابل ضرب باشد؛ پس از خود فیلم‌های پسندیده‌شده ساخته می‌شود تا سلیقه را در فضای ویژگی بیان کند. جمع‌بندی: این سؤال مفهوم «نمایه کاربر» را تثبیت کرد: سلیقه، به زبان ویژگی فیلم‌های پسندیده.', '["سن و شهر در فضای ویژگی فیلم نیستند و ضرب داخلی با آن‌ها معنا ندارد.", "همین درست است: نمایه، سلیقه است به زبان ویژگی فیلم‌ها.", "امتیاز جمع به یک فیلم، داده راه مشارکتی است، نه نمایه این کاربر.", "پرفروش بودن عمومی است و سلیقه شخصی این کاربر را نشان نمی‌دهد."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-9-B', 5, 1, 'انصاف در دیده شدن', 'انصاف با تک‌معیاره بودن ساخته نمی‌شود؛ معیارهای دوم و سوم باید آگاهانه به طراحی اضافه شوند. جمع‌بندی: این سؤال مفهوم «انصاف در طراحی» را تثبیت کرد: معیار دوم و سوم، کنار کلیک.', '["تک‌معیاره بودن کلیک دقیقاً همان دامی است که در گام ۵ گفته شد.", "همین درست است: تنوع و دیده شدن تازه‌ها به‌عنوان معیار، حباب و تمرکز را تعدیل می‌کند.", "فقط پرفروش‌ها یعنی تمرکز بیشتر دیده شدن روی همان محبوب‌های همیشگی.", "مخفی کردن دلیل، اعتماد را کم می‌کند و به انصاف کمکی نمی‌کند."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-9-B', 6, 1, 'ترکیب دو راه', 'نقطه قوت هر راه، نقطه ضعف دیگری را می‌پوشاند: شروع سرد با محتوا و غافلگیری و دقت جمعی با مشارکت. جمع‌بندی: این سؤال مفهوم «ترکیب دو راه» را تثبیت کرد: محتوا برای شروع سرد و مشارکت برای تیز شدن.', '["هر دو راه به‌تنهایی هم کار می‌کنند؛ ترکیب برای پوشش ضعف‌های هر کدام است.", "همین درست است: ترکیب، پوشش متقابل نقطه ضعف‌هاست.", "قانونی در کار نیست؛ تصمیم مهندسی و محصولی است.", "دو مدل همیشه بهتر نیست؛ این‌جا دلیل مشخص ترکیب، پوشش شروع سرد و تیز شدن حدس است."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-10-B', 1, 1, 'خواندن سیاست از Q', 'هر دو مسیر به گنج می‌رسند، ولی چپ زودتر می‌رسد: ۰٫۹ × ۱۰۰ = ۹۰ در برابر مسیر چهارقدمه ۰٫۹³ × ۱۰۰ = ۷۲٫۹؛ سیاست بزرگ‌ترین Q را می‌گیرد. جمع‌بندی: این سؤال مفهوم «سیاست بهینه» را تثبیت کرد: انتخاب عمل با Q بزرگ‌تر، حتی وقتی هر دو به مقصد می‌رسند.', '["طولانی‌تر بودن با تخفیف یعنی بازگشت کمتر، نه یادگیری بهتر در این سنجه.", "همین درست است: چپ، با Q = ۹۰.", "رسیدن مهم است، ولی زمان رسیدن با γ در بازگشت حساب شده و دو عمل برابر نیستند.", "Q سنجه بازگشت است، نه ریسک؛ کوچک‌تر بودنش مزیت نیست."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-10-B', 2, 0, 'کاربرد بلمن', 'بلمن فقط بهترین عمل بعدی را می‌گیرد: ۰ + ۰٫۹ × ۵۰ = ۴۵. جمع‌بندی: این سؤال مفهوم «max در بلمن» را تثبیت کرد: فقط بهترین Q حالت بعدی، با تخفیف.', '["همین درست است: max یعنی ۵۰ و با تخفیف می‌شود ۴۵.", "۵۰ بدون تخفیف است؛ یک قدم فاصله باید در γ ضرب شود.", "۳۶ یعنی عمل ضعیف‌تر (۴۰) انتخاب شده است؛ بلمن بهترین را می‌خواهد.", "۹۰ جمع دو Q است؛ در بلمن جمعی از دو عمل در کار نیست."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-10-B', 3, 1, 'پاداش طراحی‌شده ماه‌نشین', 'پاداش باید رفتار هدف را بسازد: نزدیک شدن و آرام شدن خوب است و سقوط بد؛ عامل دقیقاً همان چیزی را یاد می‌گیرد که پاداش می‌گوید. جمع‌بندی: این سؤال مفهوم «طراحی پاداش» را تثبیت کرد: عامل همان را یاد می‌گیرد که پاداش تعریف می‌کند.', '["سرعت زیاد هنگام فرود یعنی سقوط؛ پاداش دادن به آن سیاست ویرانگر می‌سازد.", "همین درست است: پاداش هم‌جهت با هدف فرود آرام.", "پاداش ثابت هیچ رفتاری را از رفتار دیگر بهتر نمی‌کند و چیزی یاد گرفته نمی‌شود.", "خاموشی در ارتفاع یعنی سقوط آزاد؛ خلاف هدف فرود آرام است."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-10-B', 4, 1, 'بهره‌برداری در برابر کاوش', 'Qهای اولیه نادقیق‌اند؛ بدون کاوش، برآورد اشتباه اولیه اصلاح نمی‌شود و عامل بهترین راه را کشف‌نکرده باقی می‌ماند. جمع‌بندی: این سؤال مفهوم «دام نبود کاوش» را تثبیت کرد: برآورد اولیه اشتباه، بدون امتحان اصلاح نمی‌شود.', '["پر شدن حافظه مسئله این دام نیست؛ مسئله، ندیدن گزینه بهتر است.", "همین درست است: قفل شدن روی برآورد اولیه، بهای نبود کاوش است.", "پاداش صفر نمی‌شود؛ پاداش متوسط می‌گیرد و بهترش را از دست می‌دهد.", "بدون کاوش سیاست کاملاً حریص و ثابت می‌شود، نه تصادفی."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-10-B', 5, 1, 'هدف از γ در بلمن', 'آینده یک قدم دورتر است؛ ضرب در γ همان تخفیف یک قدمه است و بدون آن، Q امروز با Q فردا هم‌تراز حساب نمی‌شد. جمع‌بندی: این سؤال مفهوم «γ در بلمن» را تثبیت کرد: تخفیف یک قدم برای بخش آینده.', '["γ کمتر از یک است و کم می‌کند، نه دو برابر.", "همین درست است: γ تخفیف یک قدم تأخیر برای بخش آینده است.", "شمارش عمل‌ها در max خلاصه شده است؛ γ فقط ضریب ارزش است.", "Q می‌تواند ۸۱ باشد؛ نگه داشتن بین صفر و یک کار γ نیست."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-10-B', 6, 1, 'چک بلمن با عدد', 'فرمول بلمن همین درس: Q = R + γ × max Q بعدی = ۰ + ۰٫۹ × ۱۰۰ = ۹۰؛ همان عدد جدول گام ۲ برای خانه ۳. جمع‌بندی: این سؤال مفهوم «معادله بلمن» را تثبیت کرد: Q هر خانه از بهترین Q خانه بعدی، با یک قدم تخفیف، ساخته می‌شود.', '["۱۰۰ خود بهترین Q بعدی است؛ تخفیف γ هنوز رویش ننشسته است.", "همین درست است: ۰٫۹ × ۱۰۰ = ۹۰.", "۸۱ چک بلمن خانه ۴ بود که از روی ۹۰ ساخته شد؛ این سؤال یک خانه عقب‌تر است.", "صفر فقط وقتی است که ارزش آینده هم صفر باشد؛ این‌جا ۱۰۰ است."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-11-B', 1, 0, 'تشخیص ساخت‌یافته', 'ستون‌های تاریخ و کالا و مبلغ معنای ثابت دارند؛ همین تعریف ساخت‌یافته است. جمع‌بندی: این سؤال مفهوم «تشخیص ساخت‌یافته» را تثبیت کرد: ستون با معنای ثابت.', '["همین درست است: جدول با ستون‌های معنادار.", "ویدیو رشته‌ای از عکس‌های غیرساخت‌یافته است.", "صدا موج است و ستون آماده ندارد.", "عکس، حتی از یک جدول، باز هم پیکسل است و غیرساخت‌یافته حساب می‌شود."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-11-B', 2, 2, 'تشخیص غیرساخت‌یافته', 'متن ایمیل دنباله‌ای از کلمه‌هاست و ستون معنادار آماده ندارد. جمع‌بندی: این سؤال مفهوم «تشخیص غیرساخت‌یافته» را تثبیت کرد: متن خام ستون آماده ندارد.', '["این جدول ستون‌های معنادار دارد و ساخت‌یافته است.", "اسم و نمره دو ستون با معنای ثابت‌اند؛ ساخت‌یافته است.", "همین درست است: متن خام، غیرساخت‌یافته است.", "دما و روز ستون‌های روشن‌اند؛ ساخت‌یافته است."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-11-B', 3, 1, 'نقش x و y', 'ورودی عکس است و خروجی یک عدد دودویی: ۱ یعنی گربه هست و ۰ یعنی نیست. جمع‌بندی: این سؤال مفهوم «نقش x و y» را تثبیت کرد: x ورودی و y جواب.', '["جهت برعکس است؛ برچسب جواب است و جواب همیشه y است.", "همین درست است: عکس وارد و برچسب بیرون می‌آید.", "خروجی باید جواب مسئله باشد، نه کپی ورودی.", "قیمت مال مسئله رگرسیون خانه‌هاست."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-11-B', 4, 1, 'خانواده شبکه برای صدا', 'شبکه بازگشتی برای دنباله‌ها ساخته شده است و قدم‌به‌قدم در زمان پیش می‌رود؛ ساختش در فاز ۸ می‌آید. جمع‌بندی: این سؤال مفهوم «خانواده شبکه برای صدا» را تثبیت کرد: دنباله زمانی یعنی شبکه بازگشتی.', '["کانولوشنی خانواده عکس‌هاست، با همسایگی دوبعدی.", "همین درست است: بازگشتی برای داده ترتیبی و زمانی.", "درخت تصمیم از فاز ۲ ابزار جدول‌های کوچک است، نه دنباله صوتی.", "K-means ابزار خوشه‌بندی فاز ۳ است و نمره و برچسبی در کارش نیست."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-11-B', 5, 1, 'مزیت روی غیرساخت‌یافته', 'روش‌های قدیمی روی جدول تمیز از قبل خوب بودند؛ جهش، فهمیدن عکس و صدا و متن بود که ویژگی آماده ندارند. جمع‌بندی: این سؤال مفهوم «مزیت روی غیرساخت‌یافته» را تثبیت کرد: جهش روی عکس و صدا و متن بود.', '["روی جدول تمیز، روش‌های سنتی سال‌ها خوب کار می‌کردند و هنوز می‌کنند.", "همین درست است: کشوی غیرساخت‌یافته محل جهش بود.", "داده بی‌الگو را هیچ روشی یاد نمی‌گیرد؛ مسئله، الگوی پنهان است نه نبود الگو.", "قیمت خانه مثال رگرسیون فاز ۱ است، نه میدان جهش یادگیری عمیق."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-11-B', 6, 1, 'سهم کلاس ۱ در آزمون', 'سهم کلاس ۱ یعنی ۱۲۰ ÷ ۲۰۰ = ۰٫۶؛ این شمارش در مثال کارشده گام ۲ همین درس انجام شد. جمع‌بندی: این سؤال مفهوم «سهم کلاس» را تثبیت کرد: سهم هر کلاس، تعدادش تقسیم بر کل مثال‌هاست.', '["۰٫۴ سهم کلاس ۰ است: ۸۰ ÷ ۲۰۰.", "همین درست است: ۰٫۶.", "۱٫۲ از مخرج اشتباه آمده است؛ سهم نمی‌تواند از ۱ بزرگ‌تر باشد.", "۱۲۰ تعداد مثال‌های کلاس ۱ است، نه سهمشان."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-12-B', 1, 1, 'مشتق رو به عقب', 'زنجیره رو به جلو برای حساب بود و برگشت رویش، با قانون زنجیره‌ای، سهم هر پارامتر در خطا را می‌دهد. جمع‌بندی: این سؤال مفهوم «مشتق رو به عقب» را تثبیت کرد: از زیان برگرد و شیب‌ها را زنجیره‌ای ضرب کن.', '["ترتیب مثال‌ها ربطی به جهت مشتق روی گراف ندارد.", "همین درست است: برگشت از ℒ و ضرب شیب‌های زنجیره.", "به‌هم زدن ترتیب داده کار دیگری در آموزش است و مشتق نیست.", "نرخ یادگیری یک ابرپارامتر جداست و در این برگشت نقشی ندارد."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-12-B', 2, 1, 'یک گام به‌روزرسانی', 'قانون: w − α × dw = ۳ − ۰٫۱ × ۰٫۴ = ۳ − ۰٫۰۴ = ۲٫۹۶. جمع‌بندی: این سؤال مفهوم «یک گام به‌روزرسانی» را تثبیت کرد: w تازه = w − α × dw.', '["۳٫۰۴ از جمع کردن آمده است؛ قانون به‌روزرسانی کم کردن دارد.", "همین درست است: ۲٫۹۶.", "۳٫۴ یعنی α در کار نبوده و علامت هم برعکس شده است.", "۲٫۶ یعنی dw کامل کم شده و نرخ یادگیری فراموش شده است."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-12-B', 3, 1, 'خروجی Z برداری', 'wᵀ به شکل (۱, ۴) در X به شکل (۴, ۱۰۰) ضرب می‌شود و حاصل (۱, ۱۰۰) است؛ برای هر مثال یک z. جمع‌بندی: این سؤال مفهوم «خروجی Z برداری» را تثبیت کرد: شکل Z برابر (۱, m) است.', '["(۴, ۱۰۰) شکل خود X است، نه حاصل ضرب داخلی با w.", "همین درست است: یک سطر و صد ستون، برای صد مثال.", "(۱۰۰, ۴) وارونه قرارداد دوره است.", "(۱, ۴) تعداد مثال‌ها را گم کرده است."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-12-B', 4, 1, 'پخش عدد b', 'عدد اسکالر بُعد ۱ در همه جهت‌ها دارد و پخشش روی هر شکلی آزاد است؛ همین مثال اول پخش در دوره اصلی است. جمع‌بندی: این سؤال مفهوم «پخش عدد b» را تثبیت کرد: اسکالر روی همه ستون‌ها پخش می‌شود.', '["اگر فقط به ستون اول می‌رسید، بقیه مثال‌ها بایاس نداشتند و جواب‌ها غلط می‌شد.", "همین درست است: پخش خودکار b روی همه مثال‌ها.", "نوشتن دستی همان حلقه‌ای است که برداری‌سازی حذفش کرده است.", "صفر بودن b ربطی به شدنی بودن پخش ندارد."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-12-B', 5, 0, 'خطای پخش', 'بُعد آخر بردار (۳) با بُعد آخر ماتریس (۲) روبه‌رو می‌شود و هیچ‌کدام ۱ نیستند؛ نامپای خطای شکل می‌دهد. سه گزینه دیگر، هر کدام یا بُعد برابر دارند یا بُعد ۱ و شدنی‌اند. جمع‌بندی: این سؤال مفهوم «خطای پخش» را تثبیت کرد: نابرابری بُعدها وقتی خطاست که هیچ‌کدام ۱ نباشند و برابر هم نباشند.', '["همین درست است: ۳ در برابر ۲ و هیچ‌کدام ۱ نیست؛ خطای شکل.", "این جمع شدنی است؛ بردار (۲,) از راست جور است و روی هر سه سطر پخش می‌شود.", "عدد تنها روی همه خانه‌ها پخش می‌شود و همیشه شدنی است.", "ستون (۳, ۱) بُعد ۱ دارد و روی هر دو ستون کش می‌آید."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-12-B', 6, 1, 'به‌روزرسانی با dw منفی', 'قانون به‌روزرسانی: ۱ − ۰٫۱ × (−۱٫۴) = ۱ + ۰٫۱۴ = ۱٫۱۴؛ همان حساب مثال کارشده دوم گام ۳. جمع‌بندی: این سؤال مفهوم «به‌روزرسانی با گرادیان منفی» را تثبیت کرد: dw منفی، وزن را بالا می‌برد.', '["۰٫۸۶ علامت dw را برعکس گرفته است؛ dw منفی وزن را بالا می‌برد.", "همین درست است: ۱٫۱۴.", "۲٫۴ یعنی α در کار نبوده و جهت هم برعکس شده است.", "−۰٫۴ حاصل هیچ قدم درستی از این قانون نیست؛ جواب باید نزدیک w اولیه بماند."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-13-B', 1, 1, 'هدف پس‌انتشار', 'بدون dW و db هیچ پارامتری نمی‌داند به کدام سمت و چقدر تکان بخورد؛ پس‌انتشار همین فرمان‌ها را می‌سازد. جمع‌بندی: این سؤال مفهوم «هدف پس‌انتشار» را تثبیت کرد: ساختن مشتق هزینه نسبت به هر پارامتر.', '["برچسب از داده آموزشی می‌آید، نه از الگوریتم آموزش.", "همین درست است: فرمان اصلاح همه پارامترها.", "عمق شبکه تصمیم طراحی است و پیش از آموزش گرفته می‌شود.", "نرخ یادگیری ابرپارامتر است و انسان انتخابش می‌کند."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-13-B', 2, 2, 'حساب dW[2]', 'هر وزن به‌اندازه ورودی خودش در خطا سهم می‌گیرد: ۰٫۲۷ × ۱ = ۰٫۲۷ و ۰٫۲۷ × ۲ = ۰٫۵۴. جمع‌بندی: این سؤال مفهوم «حساب dW[2]» را تثبیت کرد: dW برابر dz ضرب در ورودی همان وزن.', '["برابر گرفتن هر دو فرمان، سهم بزرگ‌تر ورودی دوم را نادیده می‌گیرد.", "ترتیب برعکس است؛ فرمان بزرگ‌تر مال ورودی بزرگ‌تر، یعنی دومی است.", "همین درست است: [۰٫۲۷, ۰٫۵۴].", "[۱, ۲] خود a[1] است، نه فرمان وزن‌ها."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-13-B', 3, 1, 'شیب ReLU در برگشت', 'مشتق ReLU برای z منفی صفر است؛ زنجیره در همان گره قطع می‌شود و آن نورون از این مثال چیزی یاد نمی‌گیرد. جمع‌بندی: این سؤال مفهوم «شیب ReLU در برگشت» را تثبیت کرد: z منفی یعنی شیب صفر و فرمان صفر.', '["دو برابر شدن در هیچ قاعده‌ای از این زنجیره نیست.", "همین درست است: شیب صفر یعنی فرمان صفر برای آن نورون.", "علامت عوض کردن کار هیچ فعال‌سازی در این جدول نیست.", "بایاس فرمان خودش را از راه دیگری می‌گیرد."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-13-B', 4, 2, 'شروع تصادفی درست', 'تفاوت، تقارن را می‌شکند و کوچک بودن، zها را از دم‌های اشباع فعال‌سازها دور نگه می‌دارد. جمع‌بندی: این سؤال مفهوم «شروع تصادفی درست» را تثبیت کرد: کوچک و متفاوت، نه صفر و نه بزرگ.', '["صفرِ یکسان یعنی تقارن کامل و نورون‌های کپی.", "برابر بودن، حتی با عدد ۱، همان بیماری تقارن را دارد.", "همین درست است: تصادفی و کوچک و متفاوت.", "شروع بزرگ، شیب‌ها را در دم سیگموید و tanh خفه می‌کند."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-13-B', 5, 1, 'شروع بایاس', 'حتی با b = ۰ برای همه، وزن‌های متفاوت خروجی‌های متفاوت می‌سازند و تقارنی در کار نیست. جمع‌بندی: این سؤال مفهوم «شروع بایاس» را تثبیت کرد: بایاس صفر اشکالی ندارد.', '["تصادفی بودن بایاس لازم نیست؛ شرط لازم، متفاوت بودن وزن‌هاست.", "همین درست است: b صفر مجاز است و W باید متفاوت شروع شود.", "عدد ۱ هیچ امتیاز خاصی برای بایاس ندارد.", "بایاس هم مثل وزن، با db خودش در هر گام به‌روز می‌شود."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-13-B', 6, 1, 'حساب dW[1]', 'عضو دوم dz[1] برابر −۰٫۲۷ است و سطر دوم dW[1] از ضرب آن در x = [۱, ۲] ساخته می‌شود: [−۰٫۲۷, −۰٫۵۴]. مثال کارشده گام ۳. جمع‌بندی: این سؤال مفهوم «حساب dW[1]» را تثبیت کرد: سطر هر نورون از dz همان نورون و ورودی لایه ساخته می‌شود.', '["این سطر نخست dW[1] است، نه سطر دوم.", "همین درست است: [−۰٫۲۷, −۰٫۵۴].", "عضو دوم علامتش را گم کرده است؛ علامت از dz می‌آید و در ضرب در ۲ مثبت نمی‌شود.", "صفر شدن مال وقتی است که شیب ReLU صفر باشد؛ این‌جا z[1]ها مثبت‌اند."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-14-B', 1, 1, 'عدد ۱۲۲۸۸', 'هر عکس ۶۴×۶۴ پیکسل دارد و هر پیکسل سه عدد رنگ؛ حاصل‌ضربشان ۱۲۲۸۸ ویژگی ورودی است. جمع‌بندی: این سؤال مفهوم «عدد ۱۲۲۸۸» را تثبیت کرد: اندازه تخت‌شده عکس ۶۴×۶۴ رنگی.', '["تعداد مثال‌ها m است و در ستون‌های X می‌نشیند، نه در n[0].", "همین درست است: ۱۲۲۸۸ = ۳ × ۶۴ × ۶۴.", "تعداد نورون لایه اول n[1] است و انتخاب طراح است.", "پارامترها از شکل Wها شمرده می‌شوند و خیلی بیشتر از این عددند."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-14-B', 2, 1, 'شکل W[1] گربه', 'قاعده (n[1], n[0]) یعنی (۲۰, ۱۲۲۸۸): بیست نورون مقصد و ۱۲۲۸۸ ورودی مبدأ. جمع‌بندی: این سؤال مفهوم «شکل W[1] گربه» را تثبیت کرد: (n[1], n[0]).', '["(۱۲۲۸۸, ۲۰) ترانهاده و برعکس قاعده است.", "همین درست است: (۲۰, ۱۲۲۸۸).", "(۲۰, ۷) هیچ‌کدام از دو عدد این لایه نیستند.", "(۱, ۱۲۲۸۸) یعنی لایه اول فقط یک نورون دارد."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-14-B', 3, 1, 'وزن‌های لایه اول', '۲۰ × ۱۲۲۸۸ = ۲۴۵۷۶۰ وزن در W[1] است؛ بایاس‌های هر لایه و وزن لایه‌های بعد در این سؤال نیستند. جمع‌بندی: این سؤال مفهوم «وزن‌های لایه اول» را تثبیت کرد: n[1] × n[0].', '["۱۲۲۸۸ تعداد ورودی‌هاست، نه حاصل‌ضربش در نورون‌های مقصد.", "همین درست است: ۲۴۵۷۶۰ وزن در لایه اول.", "۲۴۵۹۷۳ جمع همه پارامترهای هر چهار لایه است، نه فقط لایه اول.", "۱۴۰ وزن‌های لایه دوم است: ۷ × ۲۰."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-14-B', 4, 1, 'اثر پخش بر b', 'بُعد دوم b برابر ۱ است و قاعده پخش درس ۱۲-ب (فاز ۴) آن را روی همه ستون‌ها می‌کشاند. جمع‌بندی: این سؤال مفهوم «اثر پخش بر b» را تثبیت کرد: ستون b روی همه مثال‌ها پخش می‌شود.', '["اگر فقط به مثال اول می‌رسید، بقیه مثال‌ها بدون بایاس حساب می‌شدند.", "همین درست است: پخش b روی همه مثال‌ها.", "کپی دستی یعنی برگشتن به حلقه و کد نویسی اضافی؛ پخش خودکار همین کار را می‌کند.", "این شکل‌ها دقیقاً برای همین جمع طراحی شده‌اند و خطا نمی‌دهند."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-14-B', 5, 1, 'خطای شکل رایج', 'جابه‌جا کردن مقصد و مبدأ در شکل W، خطای کلاسیک این هفته است و بررسی ابعاد برای گرفتنش ساخته شده است. جمع‌بندی: این سؤال مفهوم «خطای شکل رایج» را تثبیت کرد: W را (مقصد، مبدأ) بنویس.', '["α نامناسب خطای آموزش است، نه خطای شکل.", "همین درست است: برعکس نوشتن (n[l], n[l−1]).", "کم بودن داده مسئله داده است و به شکل‌ها ربطی ندارد.", "تعداد لایه انتخاب طراحی است؛ شکل غلط، اشتباه اجراست."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-14-B', 6, 2, 'جمع پارامترهای معماری تازه', 'لایه ۱: تعداد ۵ × ۱۰۰ وزن و ۵ بایاس؛ لایه ۲: تعداد ۱ × ۵ وزن و ۱ بایاس؛ جمع می‌شود ۵۰۰ + ۵ + ۵ + ۱ = ۵۱۱. مثال کارشده گام ۳. جمع‌بندی: این سؤال مفهوم «جمع پارامترها» را روی معماری تازه تثبیت کرد: وزن و بایاس هر لایه، لایه‌به‌لایه شمرده می‌شوند.', '["۵۰۰ فقط وزن‌های لایه ۱ است.", "۵۰۵ وزن‌های لایه ۲ و بایاسش را کامل نشمرده است.", "همین درست است: ۵۱۱.", "۱۰۵ جمع اندازه لایه‌هاست و ربطی به شمارش پارامتر ندارد."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-15-B', 1, 1, 'هدف L2', 'وزن کوچک‌تر یعنی تابع ملایم‌تر؛ تابع ملایم‌تر کمتر دور تک‌مثال‌ها می‌پیچد و روی داده تازه بهتر می‌ایستد. جمع‌بندی: این سؤال مفهوم «هدف L2» را تثبیت کرد: وزن کوچک‌تر، خم ملایم‌تر، حفظ کردن کمتر.', '["جهت کار برعکس است؛ L2 وزن‌ها را کوچک نگه می‌دارد.", "همین درست است: جریمه مربع وزن‌ها و خم ملایم‌تر.", "سبد توسعه ابزار سنجش است و حذفش یعنی کوری در تصمیم‌گیری.", "لایه بیشتر قدرت مدل را بالا می‌برد و می‌تواند واریانس را بدتر کند."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-15-B', 2, 1, 'دراپ‌اوت هنگام آزمون', 'دراپ‌اوت وارونه مقیاس را همان زمان آموزش درست کرده است؛ هنگام آزمون شبکه کامل و بدون تغییر مقیاس کار می‌کند. جمع‌بندی: این سؤال مفهوم «دراپ‌اوت هنگام آزمون» را تثبیت کرد: پیش‌بینی با شبکه کامل.', '["خاموش کردن تصادفی هنگام جواب نهایی، خروجی را شانسی می‌کند و لازم هم نیست.", "همین درست است: دراپ‌اوت فقط ابزار زمان آموزش است.", "بدون نورون، شبکه‌ای در کار نیست.", "خاموش و روشن بودنش لایه‌به‌لایه نیست؛ کل سازوکار مخصوص آموزش است."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-15-B', 3, 1, 'گرادیان منفجرشونده', 'ضرب‌های پی‌درپی اثر نمایی دارند؛ ده لایه با ضریب ۱٫۵ عدد را تقریباً پنجاه‌وهشت برابر می‌کند. جمع‌بندی: این سؤال مفهوم «گرادیان منفجرشونده» را تثبیت کرد: ضرب تکراری بزرگ‌تر از یک یعنی انفجار.', '["محو شدن مال ضریب‌های کوچک‌تر از یک است، مثل ۰٫۵ به توان ۱۰.", "همین درست است: ضرب تکراری یعنی رشد نمایی.", "عمق دقیقاً همین‌جا اثرش را نشان می‌دهد؛ هر لایه یک ضرب دیگر است.", "لایه‌های اول بیشترین اثر را می‌بینند، چون زنجیره ضرب از آن‌ها می‌گذرد."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-15-B', 4, 1, 'مقیاس Xavier', 'برای tanh و سیگموید مقیاس Xavier به کار می‌رود: جذر یک تقسیم بر تعداد ورودی؛ برای ۱۰۰ می‌شود ۰٫۱. جمع‌بندی: این سؤال مفهوم «مقیاس Xavier» را تثبیت کرد: جذر (۱ تقسیم بر n) برای tanh و سیگموید.', '["۰٫۱۴۱۴ مقیاس He است و برای ReLU است، نه tanh.", "همین درست است: Xavier یعنی جذر (۱ تقسیم بر n).", "مقیاس ۱ برای لایه‌های پرورودی، ضرب‌های بزرگ و انفجار می‌سازد.", "وزن صفر بیماری تقارن درس ۱۳-ب (فاز ۴) را می‌آورد؛ همه نورون‌ها یکسان می‌مانند."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-15-B', 5, 2, 'تقریب دوطرفه گرادیان', '(۴٫۰۱ به توان ۲ منهای ۳٫۹۹ به توان ۲) تقسیم بر ۰٫۰۲ می‌شود (۱۶٫۰۸۰۱ منهای ۱۵٫۹۲۰۱) تقسیم بر ۰٫۰۲، یعنی ۰٫۱۶ تقسیم بر ۰٫۰۲، برابر ۸٫۰؛ همان مشتق دقیق ۲ × ۴. جمع‌بندی: این سؤال مفهوم «تقریب دوطرفه» را تثبیت کرد: تفاضل دو سوی θ تقسیم بر ۲ε.', '["۴ خود θ است، نه مشتقش.", "۷٫۹۹ تقریب یک‌طرفه با خطای بیشتر است؛ تقریب دوطرفه دقیق‌تر است.", "همین درست است: دوطرفه دقیقاً ۸٫۰ می‌دهد.", "۱۶ خود θ به توان ۲ است، یعنی مقدار تابع، نه مشتقش."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-15-B', 6, 0, 'توقف زودهنگام', 'تا وقتی خطای توسعه پایین می‌آید، آموزش ادامه دارد؛ از نقطه چرخش آن به بعد، مدل دارد حفظ می‌کند و ایستادن همان‌جا منظم‌سازی است. جمع‌بندی: این سؤال مفهوم «توقف زودهنگام» را تثبیت کرد: ایستادن در نقطه چرخش خطای توسعه.', '["همین درست است: نقطه ایستادن را خطای توسعه تعیین می‌کند.", "قدم اول هنوز هیچ الگویی یاد گرفته نشده است؛ ایستادن آن‌جا کم‌برازش می‌سازد.", "سبد آزمون تا پایان لازم است و حذفش نمره نهایی را از بین می‌برد.", "دراپ‌اوت از اول تا آخر آموزش یک keep_prob ثابت دارد و وسط کار خاموش نمی‌شود."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-16-B', 1, 1, 'فرمول قدم RMSprop', 'مخرج قدم از s ساخته می‌شود تا هر جهت با مقیاس خودش قدم بردارد؛ ε فقط نگهبان تقسیم بر صفر است. جمع‌بندی: این سؤال مفهوم «فرمول قدم RMSprop» را تثبیت کرد: گرادیان تقسیم بر جذر s.', '["بدون مخرج می‌شود گرادیان نزولی معمولی و نامش RMSprop نیست.", "همین درست است: صورت گرادیان و مخرج جذر میانگین مربع‌هایش.", "α نرخ قدم است و در صورت می‌نشیند، نه در مخرج.", "میانگین داده در هیچ قدم بهینه‌سازی‌ای شرکت نمی‌کند."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-16-B', 2, 0, 'اصلاح سوگیری در Adam', 'شروع از صفر بیماری مشترک هر میانگین غلتان است؛ تقسیم بر (۱ منهای β به توان t) همان جبرانی است که درس ۱۶-الف (فاز ۵) ساخت. جمع‌بندی: این سؤال مفهوم «اصلاح سوگیری در Adam» را تثبیت کرد: هر دو میانگین از صفر شروع می‌کنند.', '["همین درست است: اصلاح، اثر شروع از صفر را در قدم‌های اول پاک می‌کند.", "β₁ و β₂ عمداً نابرابرند: ۰٫۹ در برابر ۰٫۹۹۹.", "α همچنان انتخاب اصلی کاربر است و در قدم نهایی ضرب می‌شود.", "اصلاح سوگیری حساب داخلی بهینه‌ساز است و ربطی به حجم داده ندارد."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-16-B', 3, 0, 'حساب یک قدم Adam', 'در قدم اول، m می‌شود ۰٫۲ و v می‌شود ۰٫۰۰۴؛ اصلاح‌شده‌ها ۲ و ۴ می‌شوند و قدم می‌شود ۰٫۱ × ۲ تقسیم بر جذر ۴، یعنی ۰٫۱؛ پس θ تازه می‌شود ۵ منهای ۰٫۱، یعنی ۴٫۹، با این‌که گرادیان چهار برابر جدول اصلی گام بود. جمع‌بندی: این سؤال مفهوم «حساب قدم Adam» را تثبیت کرد: θ تازه یعنی θ منهای قدم تقریباً α.', '["همین درست است: ۵ − ۰٫۱ = ۴٫۹.", "۵٫۰ یعنی قدمی برداشته نشده است؛ قدم اول صفر نیست.", "۳٫۰ یعنی قدم ۲ برداشته شده؛ آن عدد خود گرادیان است، نه قدم Adam.", "۴٫۵ یعنی قدم ۰٫۵ برداشته شده؛ قدم اول با اصلاح سوگیری تقریباً α است، نه کسری از گرادیان."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-16-B', 4, 1, 'دلیل کاهش نرخ یادگیری', 'قدم بزرگ برای پیدا کردن دره خوب است و برای نشستن روی کف دره بد؛ برنامه کاهش، هر دو مرحله را با هم ممکن می‌کند. جمع‌بندی: این سؤال مفهوم «دلیل کاهش نرخ» را تثبیت کرد: قدم ریز برای نشستن روی کمینه.', '["فراموشی در کار نیست؛ مدل همان پارامترها را با قدم‌های ریزتر دقیق می‌کند.", "همین درست است: اول سرعت برای رسیدن، بعد دقت برای نشستن.", "تعداد لقمه از اندازه داده و لقمه می‌آید و به α ربطی ندارد.", "گرادیان نزدیک کمینه کوچک می‌شود، ولی دلیل کاهش α رفتار قدم است، نه صفر شدن گرادیان."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-16-B', 5, 0, 'کاهش نمایی', 'کاهش نمایی یعنی ضرب ساده: ۰٫۲ × ۰٫۹۵ = ۰٫۱۹. جمع‌بندی: این سؤال مفهوم «کاهش نمایی» را تثبیت کرد: هر دور یک ضرب در عامل ثابت کوچک‌تر از یک.', '["همین درست است: هر دور یک ضرب در ۰٫۹۵.", "۰٫۱ نصف نرخ آغازین است و از دستور تقسیمی دور اول می‌آید، نه کاهش نمایی.", "۰٫۲۵ از نرخ آغازین هم بزرگ‌تر است؛ کاهش یعنی کوچک‌تر شدن.", "۰٫۰۰۵ خود ضریب کاهش منهای یک است، نه نرخ تازه."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-16-B', 6, 1, 'نقش ε در Adam و RMSprop', 'وقتی s یا v اصلاح‌شده خیلی کوچک شود، مخرج بدون ε می‌تواند صفر شود؛ ε نگهبان عددی است و در اندازه قدم نقش محسوسی ندارد. جمع‌بندی: این سؤال مفهوم «نقش ε» را تثبیت کرد: نگهبان تقسیم بر صفر در مخرج قدم.', '["نرخ یادگیری α است و جدا از ε انتخاب می‌شود.", "همین درست است: ε یعنی بیمه تقسیم، نه تنظیم سرعت.", "β₂ ضریب میانگین مربع گرادیان است و معمولاً ۰٫۹۹۹ است، نه ۱۰ به توان منفی ۸.", "تعداد دور را کاربر با برنامه آموزش تعیین می‌کند."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-17-B', 1, 1, 'ترتیب قدم‌های نرمال‌سازی دسته‌ای', 'آمار از همان دسته قدم جاری می‌آید، نرمال‌سازی با همان آمار انجام می‌شود و γ و β در پایان، خروجی را به مقیاس دلخواه شبکه می‌برند. جمع‌بندی: این سؤال مفهوم «ترتیب نرمال‌سازی دسته‌ای» را تثبیت کرد: آمار دسته، نرمال، مقیاس آموختنی.', '["γ در پایان راه است، نه در شروع؛ اول باید داده نرمال شده باشد.", "همین درست است: آمار دسته، نرمال‌سازی، بعد γ و β آموختنی.", "آمار کل آموزش مال نرمال‌سازی ورودی ثابت است؛ نرمال‌سازی دسته‌ای در هر قدم و هر لایه تازه حساب می‌شود.", "آمار آزمون در هیچ قدمی از آموزش یا پیش‌بینی شرکت نمی‌کند."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-17-B', 2, 1, 'حساب خروجی نرمال‌سازی', 'میانگین دسته ۴ و انحراف معیارش حدود ۱٫۶۳۳ است؛ نرمال عدد ۶ می‌شود (۶ − ۴) تقسیم بر ۱٫۶۳۳ یعنی حدود ۱٫۲۲۴۷ و خروجی نهایی ۳ × ۱٫۲۲۴۷ − ۱ = ۲٫۶۷۴۲ است. جمع‌بندی: این سؤال مفهوم «حساب خروجی نرمال‌سازی» را تثبیت کرد: γ ضرب‌در نرمال، به‌علاوه β.', '["۴ خود میانگین دسته است و به خروجی ربطی ندارد.", "همین درست است: اول نرمال، بعد ضرب در γ و کم کردن β.", "۱٫۲۲۴۷ مقدار نرمال است پیش از γ و β؛ قدم آخر جا افتاده است.", "۳٫۶۷۴۲ یعنی β به‌جای کم شدن، جمع شده است؛ β این‌جا ۱- است."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-17-B', 3, 1, 'دلیل کارکرد نرمال‌سازی دسته‌ای', 'لایه‌های جلویی در هر قدم عوض می‌شوند؛ قفل کردن آمار ورودی هر لایه یعنی هر لایه روی توزیعی ثابت‌تر یاد می‌گیرد و نرخ‌های بزرگ‌تر هم قابل تحمل می‌شوند. جمع‌بندی: این سؤال مفهوم «دلیل نرمال‌سازی دسته‌ای» را تثبیت کرد: ورودی باثبات برای هر لایه.', '["γ و β حتی دو پارامتر تازه به هر ویژگی اضافه می‌کنند؛ صرفه‌جویی پارامتری در کار نیست.", "همین درست است: ثابت نگه داشتن توزیع ورودی لایه‌ها.", "سبد توسعه همچنان ابزار همه تصمیم‌هاست و هیچ لایه‌ای حذفش نمی‌کند.", "گرادیان صفر یعنی یادگیری مرده است؛ نرمال‌سازی برای زنده و پایدار شدن یادگیری است."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-17-B', 4, 1, 'چارچوب یادگیری عمیق', 'پس‌انتشار دست‌نویس خطاخیز است و اجرای خام روی پردازنده معمولی کند؛ چارچوب هر دو را به‌علاوه کتابخانه قطعه‌های آزموده‌شده می‌دهد. جمع‌بندی: این سؤال مفهوم «چارچوب یادگیری عمیق» را تثبیت کرد: مشتق خودکار، سرعت و قطعه آماده.', '["داده و برچسب و کاربرد همچنان کار تیم پروژه است، نه چارچوب.", "همین درست است: خودکارسازی مشتق، سرعت سخت‌افزاری و قطعه آماده.", "انتخاب ابرپارامتر دقیقاً همان هنر درس ۱۷-الف (فاز ۵) است و به انسان می‌ماند.", "سبد آزمون قانون روش کار است و ابزاری آن را دور نمی‌زند."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-17-B', 5, 1, 'زیان سافت‌مکس', 'زیان یعنی منفی لگاریتم طبیعی احتمال کلاس درست: منفی لگاریتم ۰٫۶۷ می‌شود حدود ۰٫۴۰؛ همان عددی که درس ۵-ب (فاز ۲) برای سافت‌مکس داشت. جمع‌بندی: این سؤال مفهوم «زیان سافت‌مکس» را تثبیت کرد: منفی لگاریتم احتمال کلاس درست.', '["۰٫۶۷ خود احتمال است؛ زیان لگاریتمش است، نه خودش.", "همین درست است: زیان = ‎−ln(۰٫۶۷) ≈ ۰٫۴۰.", "۲٫۴۱ زیان احتمال کوچک ۰٫۰۹ است، یعنی حدس مطمئن روی کلاس غلط.", "زیان صفر فقط برای احتمال دقیقاً یک است؛ ۰٫۶۷ هنوز فاصله دارد."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-17-B', 6, 1, 'آمار جاری هنگام آزمون', 'در این درس خواندی که هنگام آموزش، میانگین غلتانِ میانگین‌ها و واریانس‌های دسته‌ها (آمار جاری) نگه داشته می‌شود و هنگام آزمون همان به کار می‌رود؛ چون دسته آزمون ممکن است کوچک یا حتی تک‌نمونه باشد و آمار خودش قابل اتکا نیست. جمع‌بندی: این سؤال مفهوم «آمار جاری» را تثبیت کرد: هنگام آزمون، آمار نگه‌داشته‌شده از آموزش به کار می‌رود.', '["دسته آزمون ممکن است یک نمونه تنها باشد؛ میانگین خودش ترازوی درستی نیست.", "همین درست است: آمار جاریِ نگه‌داشته‌شده از آموزش، ترازوی زمان آزمون است.", "آمار کل آزمون هم در دسترس نیست و هم قانون این درس نیست.", "لایه سر جایش می‌ماند؛ فقط منبع آمارش عوض می‌شود."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-18-B', 1, 1, 'انتخاب با معیار واحد', 'معیار واحد از پیش F1 تعیین شده است؛ حساب F1 برنده را روشن می‌کند و برنده مدل الف است. جمع‌بندی: این سؤال مفهوم «انتخاب با معیار واحد» را تثبیت کرد: معیار از پیش معلوم است و حساب، برنده را معلوم می‌کند.', '["دقت تنها یکی از دو ورودی بود؛ قضاوت با آن یعنی برگشتن به بن‌بست پیش از معیار واحد.", "همین درست است: ۰٫۹۲۴ بزرگ‌تر از ۰٫۹۱۰ است.", "دو عدد F1 برابر نیستند؛ اختلاف ۰٫۰۱۴ همان تصمیم است.", "زمان اجرا در این موقعیت معیار نیست؛ اگر بود، باید از اول راضی‌کننده اعلام می‌شد."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-18-B', 2, 1, 'راضی‌کننده در صلح‌توپیا', 'راضی‌کننده شرط ورود است؛ دقت بالاتر مدلی که شرط را رد نکرده است، شمرده نمی‌شود. جمع‌بندی: این سؤال مفهوم «راضی‌کننده در عمل» را تثبیت کرد: رد نشدن از آستانه یعنی حذف، حتی با بهینه‌ساز بهتر.', '["بهینه‌ساز فقط میان مدل‌هایی مقایسه می‌شود که از آستانه گذشته باشند.", "همین درست است: اول آستانه، بعد بیشینه.", "نزدیک بودن به آستانه، رد شدن از آن نیست؛ ۱۴۰ بزرگ‌تر از ۱۰۰ است.", "مدل ج هر دو شرط بازی را دارد؛ کنار رفتن هر دو بی‌دلیل است."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-18-B', 3, 1, 'درمان سوگیری پرهیزپذیر', 'فاصله بزرگ‌تر، سوگیری پرهیزپذیر است؛ درمانش قدرت بیشتر برای خود مدل است، نه ترمز و نه داده تازه. جمع‌بندی: این سؤال مفهوم «درمان سوگیری پرهیزپذیر» را تثبیت کرد: فاصله ۷٫۵ درصدی با مدل قوی‌تر بسته می‌شود.', '["داده بیشتر درمان واریانس است؛ واریانس این‌جا فقط ۲ درصد است.", "همین درست است: اول فاصله بزرگ‌تر درمان می‌شود.", "منظم‌سازی روی مدلی که روی آموزش هم جا نمی‌شود، سوگیری را بدتر می‌کند.", "کوچک کردن توسعه فقط سنجش را ضعیف می‌کند و هیچ فاصله‌ای را نمی‌بندد."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-18-B', 4, 1, 'درمان واریانس', 'آموزش به سقف چسبیده است و شکاف تا توسعه باز مانده است؛ این دقیقاً امضای واریانس است. جمع‌بندی: این سؤال مفهوم «درمان واریانس» را تثبیت کرد: شکاف ۴٫۴ درصدی با داده و منظم‌سازی بسته می‌شود.', '["بزرگ‌تر کردن شبکه درمان فاصله‌ای است که این‌جا تقریباً صفر است.", "همین درست است: داده و منظم‌سازی، ابزار بستن شکاف آموزش تا توسعه‌اند.", "معیار در این موقعیت سالم است؛ عوض کردنش مسئله عددها را حل نمی‌کند.", "آزمون بزرگ‌تر نمره نهایی را مطمئن‌تر می‌کند؛ شکاف توسعه را نمی‌بندد."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-18-B', 5, 1, 'کند شدن نزدیک سقف', 'نزدیک کف، هر دهم درصد سخت‌تر به دست می‌آید؛ فاصله باقی‌مانده تا سقف انسان فقط نیم درصد است. جمع‌بندی: این سؤال مفهوم «کند شدن نزدیک سقف» را تثبیت کرد: نزدیکی به بیز یعنی پیشرفت سخت‌تر، نه تیم خراب‌تر.', '["از نو شروع کردن، مدلی را که به نزدیکی سقف رسیده است دور می‌اندازد.", "همین درست است: کندی نزدیک کف، قانون این بازی است.", "F1 همچنان همان کار را می‌کند؛ عددها کند شده‌اند، نه ترازو.", "صفر گرفتن سقف، فاصله‌ها را دروغین می‌کند و تیم را دنبال هدفی ناممکن می‌فرستد."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-18-B', 6, 1, 'سوگیری پرهیزپذیر زیر صفر', 'خطای آموزش زیر خطای انسان یعنی مدل از نماینده سقف رد شده است؛ فاصله منفی معنا ندارد و صفر گرفته می‌شود، همان مورد مرزی گام ۳. واریانس ۳ منهای ۰٫۳ می‌شود ۲٫۷ درصد. جمع‌بندی: این سؤال مفهوم «سوگیری پرهیزپذیر زیر صفر» را تثبیت کرد: آموزش زیر سقف انسان، سوگیری صفر و نگاه به فاصله بعدی می‌خواهد.', '["ضعیف‌تر کردن مدل برای برگشتن به سقف، هدفی وارونه است؛ جلو زدن از انسان بیماری نیست.", "همین درست است: سوگیری صفر، واریانس ۲٫۷ درصد، درمان از جعبه داده و منظم‌سازی.", "واریانس این‌جا مثبت ۲٫۷ درصد است؛ منفی بودن مال تفریق خام آموزش از انسان بود که عملاً صفر گرفته می‌شود.", "ناهم‌خوانی به سبد آموزش‌توسعه نیاز دارد و از این سه عدد خوانده نمی‌شود؛ عدد موجود واریانس را نشان می‌دهد."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-19-B', 1, 1, 'تصمیم ناهم‌خوانی در خودران', 'واریانس فقط نیم درصد است؛ فاصله ۸٫۵ درصدی میان دو دنیا می‌گوید داده آموزش باید به دنیای دوربین واقعی نزدیک شود. جمع‌بندی: این سؤال مفهوم «تصمیم ناهم‌خوانی» را تثبیت کرد: شبیه‌ساز خوب، جاده واقعی بد؛ داده را به جاده نزدیک کن.', '["منظم‌سازی درمان واریانس است و واریانس این‌جا کوچک‌ترین فاصله است.", "همین درست است: درمان فاصله بزرگ‌تر، یعنی ناهم‌خوانی.", "درباره سوگیری در این اعداد خطای انسان داده نشده است؛ عدد فریادزننده ناهم‌خوانی است.", "خطای آموزش پایین روی توزیع شبیه‌ساز است؛ محصول روی دوربین واقعی سنجیده می‌شود."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-19-B', 2, 1, 'چندوظیفه در خودران', 'چندوظیفه دقیقاً برای همین الگو ساخته شده است: یک ورودی، ویژگی‌های مشترک، چند خروجی هم‌زمان. جمع‌بندی: این سؤال مفهوم «چندوظیفه در خودران» را تثبیت کرد: ویژگی مشترک و خروجی هم‌زمان یعنی چندوظیفه.', '["شبکه‌های جدا، ویژگی‌های مشترک لبه و شکل را چهار بار از صفر یاد می‌گیرند و از کمک کارها به هم محروم می‌مانند.", "همین درست است: اشتراک لایه‌ها و چند سر خروجی.", "انتقال ترتیبی است؛ این کار هم‌زمانی می‌خواهد و هر چهار خروجی در یک لحظه لازم‌اند.", "تحلیل خطا ابزار تصمیم بعد از ساخت مدل است و جای خود معماری را نمی‌گیرد."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-19-B', 3, 1, 'سرتاسری در خودران', 'در سرتاسری هیچ تکه دست‌سازی میان راه نیست؛ هر چه تکه‌ها می‌دانستند، باید از جفت‌های ورودی و خروجی آموخته شود و این تشنگی داده می‌سازد. جمع‌بندی: این سؤال مفهوم «شرط سرتاسری» را تثبیت کرد: بدون داده جفتی فراوان، سرتاسری گرسنه می‌ماند.', '["معیار راضی‌کننده ابزار قضاوت پروژه است و به معماری داده نمی‌دهد.", "همین درست است: داده جفتی انبوه، سوخت سرتاسری است.", "آموزش‌توسعه ابزار اندازه‌گیری ناهم‌خوانی است، نه جای داده آموزش سرتاسری.", "کوچکی شبکه با داده کم جور است؛ سرتاسری معمولاً شبکه و داده بزرگ می‌خواهد."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-19-B', 4, 1, 'انتقال برای کار کم‌داده', '۲۰۰ عکس برای آموزش از صفر کم است؛ دانش آماده شبکه پرداده، دقیقاً برای همین کمبود ساخته شده است. جمع‌بندی: این سؤال مفهوم «انتقال برای کار کم‌داده» را تثبیت کرد: ویژگی مشترک و داده کم مقصد یعنی انتقال.', '["شبکه بزرگ با ۲۰۰ عکس حفظ می‌کند، یاد نمی‌گیرد؛ واریانسش منفجر می‌شود.", "همین درست است: پیش‌آموزش پرداده، تنظیم پایانی کم‌داده.", "رها کردن لازم نیست؛ انتقال راه میانه داده کم و مدل قوی است.", "آزمون برای سنجش است؛ آموزش روی آن یعنی نمره دروغین و از دست رفتن ترازو."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-19-B', 5, 1, 'ترتیب چرخه بهبود', 'چرخه فاز ۶ چنین است: ساخت سریع، سنجش، تحلیل خطا، یک تصمیم عددی؛ تغییر معماری پیش از جدول، حدس است. جمع‌بندی: این سؤال مفهوم «ترتیب چرخه بهبود» را تثبیت کرد: بعد از ساخت سریع، نوبت جدول خطاست، نه حدس تازه.', '["تعویض کامل معماری گران‌ترین حدس ممکن است و بدون جدول خطا جهتش معلوم نیست.", "همین درست است: اول جدول و سقف‌ها، بعد یک تغییر.", "آزمون برای نمره نهایی است؛ ایده گرفتن از آن، بی‌طرفی‌اش را از بین می‌برد.", "جمع داده شاید قدم بعدی باشد؛ اول باید معلوم شود کدام دسته خطا داده تازه می‌خواهد."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-19-B', 6, 1, 'تشخیص واریانس در داده ناهم‌خوان', 'واریانس یعنی آموزش‌توسعه منهای آموزش: ۱۰ منهای ۳ می‌شود ۷ درصد. ناهم‌خوانی یعنی توسعه منهای آموزش‌توسعه: ۱۱ منهای ۱۰ می‌شود ۱ درصد؛ همان سناریوی برعکس گام ۲ همین درس. جمع‌بندی: این سؤال مفهوم «تشخیص واریانس در داده ناهم‌خوان» را تثبیت کرد: سبد میانی، شکاف را به واریانس ۷ درصدی و ناهم‌خوانی ۱ درصدی جدا می‌کند.', '["۷ درصد فاصله نخست است، نه فاصله دوم؛ ناهم‌خوانی با سبد میانی تا توسعه فقط ۱ درصد است.", "همین درست است: مدل در دنیای خودش روی داده تازه بد است؛ درمانش داده همان توزیع و منظم‌سازی است.", "درباره سوگیری این اعداد خطای انسان داده نشده است و فاصله خوانا، واریانس است.", "محصول روی دوربین واقعی سنجیده می‌شود؛ خطای توسعه ۱۱ درصدی همان جای کار اصلی است."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-20-B', 1, 1, 'اندازه خروجی با گام', 'کفِ (۷ − ۳) تقسیم بر ۲ می‌شود ۲، به‌علاوه ۱ می‌شود ۳؛ خروجی ۳ در ۳ است و با عددهای گسترش گام ۲ همین درس ساخته شده است. جمع‌بندی: این سؤال مفهوم «اندازه خروجی با گام» را تثبیت کرد: کف تقسیم، به‌علاوه یک.', '["۷ اندازه ورودی است؛ بدون حاشیه و با گام ۲، خروجی بسیار کوچک‌تر می‌شود.", "همین درست است: کف‌گیری و به‌علاوه ۱ هر دو انجام شده‌اند.", "۴ شمار جای‌های گام ۱ است؛ گام ۲ نیمی از جاها را رد می‌کند.", "۲ فقط کف تقسیم است؛ به‌علاوه ۱ فرمول جا افتاده است."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-20-B', 2, 1, 'گام', 'گام اندازه پرش پنجره است؛ پرش دو خانه‌ای جای‌های لغزش را تقریباً نصف می‌کند. جمع‌بندی: این سؤال مفهوم «گام» را تثبیت کرد: پرش پنجره در هر حرکت.', '["ضخامت قاب اسمش حاشیه است و با p نشان داده می‌شود.", "همین درست است: گام، پرش پنجره است.", "شمار فیلتر عمق خروجی را معلوم می‌کند، نه جای‌های لغزش را.", "نرخ یادگیری مال آموزش است؛ گام مال شکل لایه است."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-20-B', 3, 1, 'عمق خروجی', 'هر فیلتر یک نقشه ویژگی می‌سازد؛ ۱۰ فیلتر یعنی ۱۰ نقشه روی هم، یعنی عمق ۱۰. جمع‌بندی: این سؤال مفهوم «عمق خروجی» را تثبیت کرد: عمق خروجی برابر شمار فیلترهاست.', '["۳ عمق ورودی رنگی است؛ عمق خروجی را شمار فیلترها معلوم می‌کند.", "همین درست است: یک فیلتر، یک کانال خروجی.", "۲۷ شمار وزن‌های هر فیلتر است، نه عمق خروجی.", "۱۳ جمع عمق ورودی و شمار فیلترهاست و معنایی ندارد."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-20-B', 4, 1, 'تجمیع و عمق', 'تجمیع روی هر کانال جدا انجام می‌شود و فقط طول و عرض را کوچک می‌کند؛ عمق دست نمی‌خورد. جمع‌بندی: این سؤال مفهوم «تجمیع و عمق» را تثبیت کرد: تجمیع فقط طول و عرض را کم می‌کند.', '["۵ نصف عمق است؛ تجمیع کانال‌ها را با هم قاطی نمی‌کند.", "همین درست است: ده کانال وارد می‌شود و ده کانال بیرون می‌آید.", "۲۰ دو برابر شدن است و هیچ عملی در تجمیع آن را نمی‌سازد.", "۲ اندازه پنجره تجمیع است، نه عمق خروجی."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-20-B', 5, 1, 'حاشیه هم‌اندازه', 'با p برابر ۱، صورت فرمول می‌شود n + ۲ − ۳ + ۱، یعنی همان n؛ یک قاب یک‌خانه‌ای کافی است. جمع‌بندی: این سؤال مفهوم «حاشیه هم‌اندازه» را تثبیت کرد: برای فیلتر ۳، قاب ۱.', '["حاشیه صفر خروجی را دو خانه در هر جهت کوچک می‌کند.", "همین درست است: برای فیلتر فرد، حاشیه (f − ۱) تقسیم بر ۲ است.", "حاشیه ۳ خروجی را از ورودی بزرگ‌تر می‌کند.", "حاشیه ۲ هم خروجی را دو خانه بزرگ‌تر می‌کند."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-20-B', 6, 1, 'ترتیب لایه‌ها', 'اول ویژگی‌ها با پنجره ساخته و فشرده می‌شوند، بعد بخش کاملاً متصل روی ویژگی‌های آماده تصمیم می‌گیرد. جمع‌بندی: این سؤال مفهوم «ترتیب لایه‌ها» را تثبیت کرد: اول دیدن و فشردن، بعد تصمیم.', '["سافت‌مکس پایان کار است؛ اول راه گذاشتنش یعنی تصمیم پیش از دیدن.", "همین درست است: اسکلت نمونه گام ۵.", "شبکه کاملاً متصل تنها، همان راه گران فاز ۴ است که کانولوشن برای فرار از آن آمد.", "تجمیع چیزی را فشرده می‌کند که کانولوشن ساخته باشد؛ پیش از آن چیزی برای فشردن نیست."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-21-B', 1, 1, 'حساب میان‌بُر', 'جمع میان‌بُر می‌شود ۱٫۰ منهای ۰٫۴، یعنی ۰٫۶ و ReLU عدد مثبت را دست نمی‌زند؛ همان حساب گسترش گام ۲ همین درس است. جمع‌بندی: این سؤال مفهوم «حساب میان‌بُر» را تثبیت کرد: gِ (z + a)، حتی وقتی z منفی است.', '["‎−۰٫۴ فقط z است؛ میان‌بُر در این عدد نیست و ReLU هم عدد منفی را صفر می‌کرد.", "همین درست است: اول جمع میان‌بُر، بعد فعال‌ساز.", "۱٫۴ قدرمطلق دو عدد را جمع کرده است؛ z این‌جا منفی است و از a کم می‌شود.", "۱٫۰ فقط ورودی است؛ سهم خود بلوک جا افتاده است."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-21-B', 2, 1, 'پارامتر یک‌در‌یک', 'هر فیلتر ۲۵۶ وزن و یک بایاس دارد، یعنی ۲۵۷؛ ضرب‌در ۶۴ می‌شود ۱۶۴۴۸. جمع‌بندی: این سؤال مفهوم «پارامتر یک‌در‌یک» را تثبیت کرد: عمق ورودی، به‌علاوه یک، ضرب‌در شمار فیلتر.', '["۶۴ فقط شمار فیلترهاست؛ وزن هر فیلتر شمرده نشده است.", "همین درست است: (۲۵۶ + ۱) × ۶۴.", "۱۶۳۸۴ بایاس‌های ۶۴ فیلتر را جا انداخته است.", "۲۵۶ عمق ورودی است، نه شمار پارامتر لایه."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-21-B', 3, 1, 'عمق خروجی اینسپشن', 'خروجی شاخه‌ها در عمق کنار هم چیده می‌شوند؛ جمع چهار عمق ۵۶ می‌شود. جمع‌بندی: این سؤال مفهوم «عمق خروجی اینسپشن» را تثبیت کرد: جمع عمق شاخه‌ها.', '["۲۴ فقط بزرگ‌ترین شاخه است؛ بقیه شاخه‌ها هم در خروجی هستند.", "همین درست است: چیدن در عمق یعنی جمع عمق‌ها.", "۸ عمق دو شاخه کوچک است و بقیه را حذف می‌کند.", "۴ شمار شاخه‌هاست، نه عمق خروجی."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-21-B', 4, 1, 'گلوگاه', 'خرج فیلتر بزرگ با عمق ورودی ضرب می‌شود؛ باریک کردن عمق، خرج را چند برابر کم می‌کند. جمع‌بندی: این سؤال مفهوم «گلوگاه» را تثبیت کرد: باریک کردن عمق پیش از کار گران.', '["میدان دید را خود فیلتر ۵ در ۵ معلوم می‌کند؛ گلوگاه روی عمق کار می‌کند.", "همین درست است: اول باریک کن، بعد فیلتر بزرگ.", "شاخه تجمیع سر جایش می‌ماند و گلوگاه ربطی به آن ندارد.", "ثابت نگه داشتن وزن مال یادگیری انتقالی است، نه گلوگاه."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-21-B', 5, 1, 'تنظیم دقیق', 'تنظیم دقیق پله دوم انتقال است؛ چشم آماده می‌ماند و تخصص کار تو آرام رویش می‌نشیند. جمع‌بندی: این سؤال مفهوم «تنظیم دقیق» را تثبیت کرد: بازآموزی ملایم، نه از صفر و نه برای همیشه ثابت.', '["حذف لایه یعنی دور ریختن همان چیزی که قرض گرفته شده است.", "همین درست است: بازآموزی ملایم لایه‌های آخر.", "از صفر شروع کردن نقض خود ایده انتقال است.", "ثابت نگه داشتن همه لایه‌ها پله نخست است؛ تنظیم دقیق یک قدم جلوتر می‌رود."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-21-B', 6, 1, 'کانولوشن جداشدنی موبایل‌نت', 'کانولوشن جداشدنی عمقی، ضرب‌های سطح و کانال را از هم جدا می‌کند و پارامتر را نزدیک هشت برابر کم می‌کند. جمع‌بندی: این سؤال مفهوم «کانولوشن جداشدنی» را تثبیت کرد: سطح جدا، کانال جدا.', '["فیلتر ۳ در ۳ می‌ماند؛ فقط کارش به دو قدم ارزان تقسیم می‌شود.", "همین درست است: اول در کانال، بعد میان کانال‌ها.", "اندازه عکس انتخاب دیگری است؛ ترفند در خود عمل کانولوشن است.", "محل آموزش ربطی به سبکی مدل روی گوشی ندارد؛ مدل باید سبک باشد."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-22-B', 1, 1, 'IoU از روی مساحت‌ها', 'اجتماع می‌شود ۲۰ به‌علاوه ۱۲ منهای ۶، یعنی ۲۶؛ ۶ تقسیم بر ۲۶ حدود ۰٫۲۳ می‌شود؛ همان حساب گسترش گام ۲ همین درس و از آستانه درستی ۰٫۵ پایین‌تر است. جمع‌بندی: این سؤال مفهوم «IoU از روی مساحت‌ها» را تثبیت کرد: اشتراک تقسیم بر اجتماع، با مساحت‌های آماده.', '["۰٫۳۰ نسبت اشتراک به مساحت جعبه واقعی است، نه به اجتماع.", "همین درست است: مخرج، اجتماع است و مشترک در آن یک بار شمرده می‌شود.", "۰٫۵۰ خود آستانه درستی است، نه جواب این حساب.", "۰٫۱۹ مخرج را جمع ساده دو مساحت گرفته و مشترک را کم نکرده است."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-22-B', 2, 1, 'روند حذف غیربیشینه', 'بالاترین اطمینان می‌ماند؛ هم‌پوشانی ۰٫۸ یعنی همان شئ و حذف؛ هم‌پوشانی ۰٫۲ یعنی جای دیگر و ماندن. جمع‌بندی: این سؤال مفهوم «روند حذف غیربیشینه» را تثبیت کرد: نگه دار، هم‌جا را حذف کن، تکرار کن.', '["جعبه سوم جایش فرق دارد و احتمالاً شئ دوم است؛ حذفش یعنی از دست دادن یک شئ واقعی.", "همین درست است: یک جعبه برای هر جای متمایز.", "ماندن دومی یعنی یک شئ با دو جعبه گزارش می‌شود.", "جعبه سوم کم‌اطمینان‌ترین است و به‌تنهایی ماندنش هر دو قاعده را برعکس می‌کند."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-22-B', 3, 1, 'یک گذر یولو', 'اسمش هم همین است: فقط یک بار نگاه می‌کنی؛ سرعت، حاصل همان یک گذر بودن است. جمع‌بندی: این سؤال مفهوم «یک گذر یولو» را تثبیت کرد: سرعت از یک‌بار دیدن می‌آید.', '["یولو هم با جعبه‌های برچسب‌دار آموزش می‌بیند؛ برتری‌اش در سرعت است.", "همین درست است: یک گذر برای همه خانه‌ها و لنگرها.", "ادعای دقیق‌ترین بودن در دوره اصلی نیست؛ مصالحه یولو سرعت در برابر کمی دقت است.", "خروجی یولو هم جعبه تکراری دارد و پایان کارش همان حذف غیربیشینه است."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-22-B', 4, 1, 'بخش‌بندی معنایی', 'جعبه پس‌زمینه را هم داخل می‌آورد؛ بخش‌بندی خود شکل را رنگ می‌کند و خروجی‌اش هم‌اندازه عکس است. جمع‌بندی: این سؤال مفهوم «بخش‌بندی معنایی» را تثبیت کرد: برچسب برای تک‌تک پیکسل‌ها.', '["رنگ عکس محدودیتی برای هیچ‌کدام نیست؛ فرق در ریزی خروجی است.", "همین درست است: پیکسل‌به‌پیکسل در برابر جعبه.", "U-Net یک شبکه کانولوشنی کامل است، با نیمه کوچک‌کننده و بزرگ‌کننده.", "تعریف برعکس شده است؛ جعبه مال تشخیص است و برچسب پیکسلی مال بخش‌بندی."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-22-B', 5, 1, 'میان‌بُر در U-Net', 'نیمه نخست برای فهم معنا نقشه را کوچک می‌کند و جزئیات مرز در راه گم می‌شود؛ میان‌بُر همان جزئیات را سر راه بزرگ شدن برمی‌گرداند. جمع‌بندی: این سؤال مفهوم «میان‌بُر در U-Net» را تثبیت کرد: جزئیات مرز، از راه میان‌بُر نجات می‌یابد.', '["برچسب نهایی پایان نیمه دوم ساخته می‌شود، نه در میان راه.", "همین درست است: دقت مکان از راه میان‌بُر برمی‌گردد.", "انتقال وزن مال یادگیری انتقالی درس ۲۱-ب (فاز ۷) است، نه این میان‌بُرها.", "حذف غیربیشینه روی خروجی جعبه‌ها کار می‌کند؛ خروجی U-Net پیکسلی است."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-22-B', 6, 2, 'مسئولیت خانه در یولو', 'هر خانه ۱۰۰ پیکسل پهنا و بلندا دارد؛ فاصله افقی ۳۵۰ در چهارمین بازه صدتایی و فاصله عمودی ۱۲۰ در دومین بازه صدتایی می‌افتد، پس خانه مسئول سطر ۲ و ستون ۴ است. جمع‌بندی: این سؤال مفهوم «مسئولیت خانه در یولو» را تثبیت کرد: خانه‌ای که مرکز شئ در آن می‌افتد، مسئول حدس آن شئ است.', '["این خانه از جابه‌جا کردن سطر و ستون به دست می‌آید، در حالی که فاصله افقی ستون و فاصله عمودی سطر را تعیین می‌کند.", "ستون چهارم درست است، ولی فاصله عمودی ۱۲۰ پیکسل در دومین بازه صدتایی می‌افتد، پس سطر باید ۲ باشد نه ۱.", "همین درست است: هر خانه ۱۰۰ پیکسل است و فاصله افقی ۳۵۰ در ستون چهارم و فاصله عمودی ۱۲۰ در سطر دوم قرار می‌گیرد.", "سطر دوم درست است، ولی فاصله افقی ۳۵۰ پیکسل از مرز ۳۰۰ گذشته و وارد ستون چهارم شده است، نه ستون سوم."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-23-B', 1, 1, 'زیان سه‌تایی', '۰٫۰۸ منهای ۰٫۲۵ به‌علاوه ۰٫۲ می‌شود ۰٫۰۳؛ مثبت برنده است ولی هنوز به اندازه حاشیه جلو نیست. جمع‌بندی: این سؤال مفهوم «زیان سه‌تایی» را تثبیت کرد: فاصله مثبت، منهای فاصله منفی، به‌علاوه حاشیه، با کف صفر.', '["صفر وقتی است که برتری مثبت دست‌کم ۰٫۲ باشد؛ این‌جا برتری ۰٫۱۷ است.", "همین درست است: بیشینه صفر و همین حساب، خود ۰٫۰۳ است.", "۰٫۱۷ فقط برتری فاصله منفی بر مثبت است و حاشیه در آن نیست.", "۰٫۳۷ جمع بی‌قاعده سه عدد است و تفاضل فاصله‌ها در آن گم شده است."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-23-B', 2, 1, 'تصمیم دربان', 'قاعده راستی‌آزمایی فاصله کمتر از آستانه است؛ ۰٫۰۸ کمتر از ۰٫۱ است. جمع‌بندی: این سؤال مفهوم «تصمیم دربان» را تثبیت کرد: فاصله زیر آستانه، همان آدم.', '["فاصله صفر یعنی دو عکس عین هم؛ دو عکس متفاوت از یک آدم هیچ‌وقت صفر نمی‌شوند.", "همین درست است: کمتر از آستانه یعنی پذیرش.", "جهت قاعده برعکس گفته شده است؛ فاصله بزرگ نشانه بیگانگی است.", "راستی‌آزمایی اسم نمی‌پرسد؛ با مرجع می‌سنجد."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-23-B', 3, 1, 'هزینه کل سبک', '۱۰ ضرب‌در ۲ می‌شود ۲۰ و ۴۰ ضرب‌در ۵ می‌شود ۲۰۰؛ جمعشان ۲۲۰ است. جمع‌بندی: این سؤال مفهوم «هزینه کل سبک» را تثبیت کرد: آلفا در محتوا، به‌علاوه بتا در سبک.', '["۷۰ فقط وزن‌ها و هزینه‌ها را جدا جدا جمع کرده و ضرب‌ها را انجام نداده است.", "همین درست است: هر هزینه اول در وزنش ضرب می‌شود.", "۵۰ حاصل ضرب آلفا در هزینه سبک به‌تنهایی هم نیست و هر دو بخش در آن گم شده‌اند.", "۲۷ جمع آلفا و بتا و دو هزینه است، بدون هیچ ضربی."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-23-B', 4, 1, 'گرم دو کانال', 'در هر جا دو فعال‌سازی در هم ضرب و بعد جمع می‌شوند: ۱ ضرب‌در ۳، به‌علاوه ۲ ضرب‌در ۰، می‌شود ۳. جمع‌بندی: این سؤال مفهوم «گرم دو کانال» را تثبیت کرد: هم‌نشینی یعنی ضرب مشترک در هر جا.', '["۵ گرم کانال نخست با خودش است، نه با کانال دوم.", "همین درست است: ضرب جفت‌ها و جمع روی جاها.", "۹ گرم کانال دوم با خودش است.", "۶ جمع ساده هر چهار عدد است و ضرب‌ها انجام نشده‌اند."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-23-B', 5, 1, 'تعادل آلفا و بتا', 'گم شدن محتوا یعنی صدای هزینه محتوا کم است؛ وزن همان بخش باید بالا برود. جمع‌بندی: این سؤال مفهوم «تعادل آلفا و بتا» را تثبیت کرد: صدای هر هزینه با وزن خودش تنظیم می‌شود.', '["بتای بیشتر سبک را از این هم پررنگ‌تر می‌کند و محتوا باز هم عقب‌تر می‌رود.", "همین درست است: هر بخش را با وزن خودش تنظیم کن.", "آستانه دربان مال راستی‌آزمایی چهره است و به این تکلیف ربطی ندارد.", "لایه نخست شباهت پیکسلی می‌سازد و راهش رونوشت است، نه نجات معنا."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-23-B', 6, 1, 'گرم دو کانال با سه جا', 'در هر سه جا دو فعال‌سازی در هم ضرب و جمع می‌شوند: ۱ ضرب‌در ۲، به‌علاوه ۰ ضرب‌در ۱، به‌علاوه ۲ ضرب‌در ۰، می‌شود ۲؛ همان حساب گسترش گام ۴ همین درس است. جمع‌بندی: این سؤال مفهوم «گرم دو کانال» را تثبیت کرد: هم‌نشینی در هر سه جا شمرده می‌شود.', '["۵ گرم هر یک از دو کانال با خودش است، نه گرم دو کانال با هم.", "همین درست است: ضرب جفت‌های هم‌جا در هر سه جا.", "۶ جمع ساده هر شش فعال‌سازی است و ضرب‌ها انجام نشده‌اند.", "۴ فقط ضرب جای سوم کانال نخست در خودش است."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-24-B', 1, 1, 'پیام محو شونده', 'همین محو شدن در جهت آموزش هم رخ می‌دهد و وصل کردن قدم‌های دور را ناممکن می‌کند؛ دروازه‌ها آمده‌اند تا سهم نگه‌داری را خود شبکه تنظیم کند. جمع‌بندی: این سؤال مفهوم «پیام محو شونده» را تثبیت کرد: محو شدن اثر دور، دلیل نیاز به دروازه است.', '["طول جمله در این مقایسه نقشی ندارد؛ هر دو حساب روی ده قدم‌اند.", "همین درست است: حساسیت به ضریب و محو شدن، دلیل تولد دروازه‌هاست.", "ضریب نیم یعنی فراموشی سریع؛ برای خاطره دور، بدترین انتخاب این جدول است.", "گرادیان در راه برگشت در همان ضریب‌ها ضرب می‌شود؛ این عددها خود مسئله گرادیان‌اند."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-24-B', 2, 1, 'حساب GRU', 'حافظه تازه میانگین وزنی دو سهم است: ‎۰٫۹ × ۰٫۵ + ۰٫۱ × ۰٫۲ = ۰٫۴۵ + ۰٫۰۲ = ۰٫۴۷‎. جمع‌بندی: این سؤال مفهوم «حساب GRU» را تثبیت کرد: حافظه تازه = سهم دروازه از نامزد + سهم باقی‌مانده از قبلی.', '["۰٫۷۰ جمع ساده دو عدد است؛ دروازه وزن می‌دهد، جمع نمی‌کند.", "همین درست است: سهم تازه ۰٫۴۵ و سهم قبلی ۰٫۰۲ می‌شود.", "۰٫۵۰ فقط نامزد تازه است؛ سهم قبلی در آن حساب نشده است.", "۰٫۲۰ فقط حافظه قبلی است؛ سهم تازه فراموش شده است."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-24-B', 3, 1, 'حساب نوار LSTM', 'بار تازه از دو راه می‌آید: ‎۰٫۸ × ۰٫۵ = ۰٫۴۰‎ از گذشته می‌ماند و ‎۰٫۳ × ۰٫۴ = ۰٫۱۲‎ تازه وارد می‌شود؛ جمعشان ۰٫۵۲ است. جمع‌بندی: این سؤال مفهوم «حساب نوار LSTM» را تثبیت کرد: بار تازه = فراموشی × قبلی + ورودی × نامزد.', '["۰٫۹۰ جمع بار و نامزد بدون دروازه‌هاست؛ دروازه‌ها سهم‌ها را تعیین می‌کنند.", "همین درست است: ۰٫۴۰ مانده از گذشته، به‌علاوه ۰٫۱۲ تازه.", "۰٫۴۰ فقط سهم گذشته است؛ ورودی تازه حساب نشده است.", "۰٫۱۲ فقط سهم تازه است؛ بار قبلی نوار از قلم افتاده است."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-24-B', 4, 1, 'نقش نوار نقاله', 'در شبکه ساده خاطره ناچار در هر قدم در ضریب کوچک ضرب می‌شد؛ در LSTM سهم ماندن بار نوار انتخاب خود شبکه است و می‌تواند نزدیک یک بماند. جمع‌بندی: این سؤال مفهوم «نوار نقاله حافظه» را تثبیت کرد: راه جدا با سهم ماندن آموختنی، خاطره دور را زنده نگه می‌دارد.', '["از نو ساختن یعنی فراموشی؛ درمان دقیقاً نگه داشتن است.", "همین درست است: راه جدا و سهم ماندن نزدیک یک، سفر طولانی بار را ممکن می‌کند.", "نامزد تازه از tanh می‌گذرد؛ نجات نوار از دست‌نخوردن نسبی راهش است، نه از نبود tanh.", "طول جمله را داده تعیین می‌کند؛ نوار فقط حافظه را در همان طول نگه می‌دارد."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-24-B', 5, 1, 'شرط دوجهته', 'نگاه به آینده به جمله کامل نیاز دارد؛ در کار زنده، جمله هنوز در حال ساخته شدن است و آینده‌ای برای خواندن نیست. جمع‌بندی: این سؤال مفهوم «شرط دوجهته» را تثبیت کرد: آینده جمله فقط وقتی هست که جمله کامل رسیده باشد.', '["دوجهته روی جمله کامل معمولاً دقیق‌تر است؛ مسئله این‌جا نبودن آینده است، نه دقت.", "همین درست است: شرط در دست بودن کل جمله در پخش زنده برقرار نیست.", "زبان جمله در این استدلال نقشی ندارد؛ مسئله زمان رسیدن داده است.", "دوجهته دو دسته وزن خواندن دارد؛ پارامترش از یک‌جهته هم بیشتر است."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-24-B', 6, 1, 'گرادیان منفجر شونده', 'ضریب‌های بزرگ‌تر از یک در زنجیره قدم‌ها رشد نمایی می‌سازند؛ محو شدن و انفجار دو سر یک طیف‌اند و دروازه‌ها و بریدن گرادیان برای مهار همین طیف آمده‌اند. جمع‌بندی: این سؤال مفهوم «گرادیان منفجر شونده» را تثبیت کرد: ضریب بالای یک در ده قدم به ۵۷٫۶۷ می‌رسد.', '["محو شدن مال ضریب‌های کوچک‌تر از یک است؛ ۵۷٫۶۷ رشد است، نه محو.", "همین درست است: انفجار، آیینه محو شدن در سر دیگر طیف است.", "شمار لایه و پارامتر در این حساب نیست؛ فقط ضریب و توان قدم‌هاست.", "این عدد از رفتار خود ضریب در زنجیره می‌آید؛ دروازه‌ها درمان‌اند، نه علت."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-25-B', 1, 1, 'منطق اسکیپ‌گرم', 'شباهت بردارها محصول فرعی فشار بازی است: دو کلمه با همسایه‌های مشترک فقط وقتی خوب حدس زده می‌شوند که بردارهایشان شبیه هم باشد. جمع‌بندی: این سؤال مفهوم «منطق اسکیپ‌گرم» را تثبیت کرد: همسایه مشترک، بردار نزدیک می‌سازد.', '["فرهنگ لغت در این بازی نیست؛ تنها داده، هم‌نشینی در متن است.", "همین درست است: بافت مشترک، بردار مشترک می‌سازد.", "اندازه پنجره انتخاب طراحی است و منطق نزدیکی را توضیح نمی‌دهد.", "متن همان متن خام آدم‌هاست؛ مرتب‌سازی معنایی در کار نیست."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-25-B', 2, 1, 'حساب نمونه‌گیری منفی', 'نمونه‌گیری منفی مسئله را دودویی می‌کند: جفت واقعی برچسب یک می‌گیرد و جفت‌های تصادفی برچسب صفر؛ مدل مرز واقعی و ساختگی را یاد می‌گیرد. جمع‌بندی: این سؤال مفهوم «نمونه‌گیری منفی در عمل» را تثبیت کرد: برچسب یک برای جفت واقعی و صفر برای جفت تصادفی.', '["معنای کلمه‌های منفی هدف نیست؛ آن‌ها فقط نقش «نه» را بازی می‌کنند.", "همین درست است: تشخیص جفت واقعی از جفت ساختگی.", "املاء در هیچ جای این آموزش سنجیده نمی‌شود.", "ترتیب جمله در جفت‌ها از پیش ثابت است؛ یادگیری روی واقعی بودن جفت است."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-25-B', 3, 2, 'جدول هم‌نشینی GloVe', '«گربه» دو بار آمده است؛ یک بار کنار «روی» و یک بار کنار «خوابید». «حصیر» دو خانه از گربه نخست فاصله دارد و در پنجره یک‌همسایه‌ای نمی‌افتد؛ شمارش صفر است. جمع‌بندی: این سؤال مفهوم «هم‌نشینی در پنجره» را تثبیت کرد: فقط کلمه‌های داخل پنجره شمرده می‌شوند.', '["۲ شمار آمدن خود «گربه» در متن است، نه هم‌نشینی‌اش با «حصیر».", "۱ شمار هم‌نشینی (گربه، روی) یا (گربه، خوابید) است، نه حصیر.", "همین درست است: فاصله دو خانه، بیرون پنجره یک‌همسایه‌ای است.", "۳ از شمردن همه هم‌نشینی‌ها با هم می‌آید؛ پرسش فقط یک جفت را می‌خواهد."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-25-B', 4, 1, 'امتیاز احساس', 'میانگین دو بردار می‌شود (۰٫۷۵ ، ۰٫۲۵) و تفاضل مؤلفه‌ها می‌شود ۰٫۵؛ امتیاز مثبت، یعنی جمله مثبت خوانده می‌شود. جمع‌بندی: این سؤال مفهوم «امتیاز احساس از میانگین» را تثبیت کرد: میانگین بردارها، بعد تفاضل مؤلفه‌ها.', '["۱٫۵ جمع مؤلفه‌هاست؛ امتیاز، تفاضل محور مثبت و محور دوم است.", "همین درست است: ۰٫۷۵ منهای ۰٫۲۵ می‌شود ۰٫۵.", "۰٫۰ یعنی خنثی؛ این جمله یک کلمه آشکارا مثبت دارد.", "−۰٫۵ علامتش برعکس است؛ محور نخست این نقشه محور مثبت بودن است."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-25-B', 5, 1, 'حساب رفع سوگیری', 'رفع سوگیری فقط مؤلفه روی جهت سوگیری را برای کلمه خنثی حذف می‌کند: ۰٫۸ می‌رود و ۰٫۶، که حامل تخصص است، می‌ماند. جمع‌بندی: این سؤال مفهوم «رفع سوگیری» را تثبیت کرد: حذف مؤلفه روی جهت سوگیری، فقط برای کلمه‌های خنثی.', '["بدون تغییر یعنی کلیشه سر جایش مانده است؛ هدف درس همین تغییر بود.", "همین درست است: حذف جهت سوگیری، نگه داشتن بقیه بردار.", "(۰٫۸ ، ۰) برعکس عمل می‌کند؛ کلیشه می‌ماند و تخصص می‌رود.", "(۰ ، ۰) یعنی نابودی خود کلمه؛ رفع سوگیری جراحی یک جهت است، نه پاک کردن بردار."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-25-B', 6, 1, 'حساب رفع سوگیری روی شغل تازه', 'مثل حساب دکتر در گام ۶: فقط مؤلفه روی جهت سوگیری، یعنی ۰٫۷، حذف می‌شود و مؤلفه دوم، یعنی ۰٫۹، که حامل تخصص است می‌ماند. جمع‌بندی: این سؤال مفهوم «رفع سوگیری روی شغل تازه» را تثبیت کرد: مؤلفه جهت سوگیری می‌رود و بقیه بردار می‌ماند.', '["بدون تغییر یعنی کلیشه سر جایش مانده است؛ هدف درس همین یک تغییر بود.", "همین درست است: حذف جهت سوگیری برای کلمه خنثی، نگه داشتن بقیه بردار.", "(۰٫۷ ، ۰) وارونه عمل می‌کند؛ کلیشه می‌ماند و تخصص می‌رود.", "(۰ ، ۰) نابودی خود کلمه است، نه جراحی یک جهت."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-26-B', 1, 1, 'گلوگاه خلاصه ثابت', 'در جمله بلند، یک بردار ثابت همه معنا را گم می‌کند؛ توجه برای هر قدم خروجی یک زمینه جدا و هدف‌گرفته می‌سازد. جمع‌بندی: این سؤال مفهوم «گلوگاه خلاصه ثابت» را تثبیت کرد: توجه، دسترسی مستقیم هر قدم خروجی به ورودی است.', '["توجه حتی حساب را بیشتر هم می‌کند؛ دردش دقت و دسترسی است، نه سرعت رمزگذار.", "همین درست است: برداشتن گلوگاه خلاصه ثابت با نگاه مستقیم هر قدم.", "داده کم با افزایش و انتقال درمان می‌شود؛ توجه معماری است، نه داده.", "سنجش ترجمه کار بلو بود و در درس ۲۶-الف (فاز ۸) حل شد."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-26-B', 2, 1, 'خواندن وزن توجه', 'بزرگ‌ترین وزن روی کلمه هم‌معنای مبدأ نشسته است؛ توجه هم‌ترازی نرم میان دو جمله را بدون هیچ برچسب دستی یاد گرفته است. جمع وزن‌ها هم یک است. جمع‌بندی: این سؤال مفهوم «هم‌ترازی توجه» را تثبیت کرد: وزن بزرگ، جای درست نگاه را برای هر کلمه نشان می‌دهد.', '["وزن کلمه نخست فقط ۰٫۰۵ است؛ نگاه روی «noir» متمرکز است.", "همین درست است: هم‌ترازی آموخته‌شده میان «black» و «noir».", "جمع چهار وزن دقیقاً یک می‌شود: ۰٫۰۵ + ۰٫۱۵ + ۰٫۷۵ + ۰٫۰۵.", "«dort» فعل جمله است و وزن کمش نشان می‌دهد برای این کلمه لازم نبوده است."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-26-B', 3, 1, 'درمان خطای مدل', 'جستجو وظیفه‌اش را انجام داده است: محتمل‌ترین جمله نزد مدل را آورده است. وقتی همان جمله بد است، درمان از جنس مدل است، نه پهنای پرتو. جمع‌بندی: این سؤال مفهوم «مرز تقصیر مدل و جستجو» را تثبیت کرد: پرتو فقط وقتی درمان است که جمله بهتر در مدل باشد و پیدا نشده باشد.', '["پرتو پهن‌تر باز هم همان جمله محتمل نزد مدل را می‌آورد؛ وقتی تقصیر با مدل است، پهنای بیشتر هیچ کمکی نمی‌کند.", "همین درست است: تقصیر مدل با ابزار مدل درمان می‌شود.", "بلو نمره نهایی را می‌سنجد؛ در ساختن این جمله نقشی نداشته است.", "واژه محرک مال سرزمین صداست و به این ترجمه ربطی ندارد."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-26-B', 4, 1, 'نشانه خالی CTC', 'صدا برای هر نویسه چندین قدم دارد؛ نشانه خالی و تکرار اجازه می‌دهد دنباله بلند صوتی روی دنباله کوتاه متنی بنشیند و بعد با حذف آن‌ها متن خوانده شود. جمع‌بندی: این سؤال مفهوم «نشانه خالی CTC» را تثبیت کرد: پل میان طول صدا و طول متن.', '["پایان جمله نشانه جدا دارد؛ خالی برای هم‌ترازی میانی است.", "همین درست است: پر کردن فاصله‌ها برای هم‌ترازی دو طول نابرابر.", "پاک کردن نویز کار پیش‌پردازش صداست، نه نشانه هم‌ترازی.", "فعال‌سازی کار آستانه احتمال واژه محرک است، درس گام ۵."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-26-B', 5, 1, 'فعال‌سازی تکراری', 'یک بار گفتن واژه، موجی از احتمال بالا در چند قدم می‌سازد؛ آشکارساز باید نخستین رد شدن را بگیرد و تا مدتی رد شدن‌های همان موج را نادیده بگیرد. جمع‌بندی: این سؤال مفهوم «فعال‌سازی تکراری» را تثبیت کرد: موج احتمال یک رویداد است و باید یک بار شمرده شود.', '["سه شنیدن جدا با یک بار گفتن جور نیست؛ موج احتمال یک رویداد است.", "همین درست است: یک موج، یک فعال‌سازی؛ درمان، پنجره بستن بعد از فعال‌سازی است.", "آستانه صفر یعنی فعال‌سازی همیشگی؛ مشکل بدتر می‌شود نه بهتر.", "جمله فقط یک واژه محرک داشت؛ شمارش قدم‌ها با شمارش گفتن‌ها یکی نیست."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-26-B', 6, 1, 'شمارش فعال‌سازی با بستن موقت', 'نخستین رد شدن در قدم دوم با ۰٫۵۵ رخ می‌دهد؛ قدم سوم با ۰٫۶ هنوز بالای آستانه است، اما داخل بستن موقت بعد از فعال‌سازی است و شمرده نمی‌شود و قدم چهارم هم پایین آستانه است. جمعاً یک فعال‌سازی برای یک بار گفتن واژه. جمع‌بندی: این سؤال مفهوم «بستن موقت بعد از فعال‌سازی» را تثبیت کرد: موج چندقدمی احتمال، یک رویداد شمرده می‌شود.', '["دو فعال‌سازی یعنی هر قدم بالای آستانه شمرده شده است؛ بستن موقت دقیقاً برای جلوگیری از همین دوباره‌شماری است.", "همین درست است: یک موج احتمال، یک فعال‌سازی.", "قدم نخست احتمالش ۰٫۴ و زیر آستانه است؛ سه فعال‌سازی از هیچ راهی درنمی‌آید.", "۰٫۵۵ و ۰٫۶ هر دو از آستانه رد شده‌اند؛ فعال‌سازی صفر ممکن نیست."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-27-B', 1, 1, 'چرا مدل آماده', 'نسبت هزینه و فایده روشن است: پیش‌آموزش یک بار و جای دیگر انجام شده است و این درس روی به کار گرفتن و قضاوت درباره خروجی تمرکز می‌کند. جمع‌بندی: این سؤال مفهوم «مدل ازپیش‌آموزش‌دیده» را تثبیت کرد: پیش‌آموزش جای دیگر، کاربرد و قضاوت این‌جا.', '["مدل‌های تازه هر روز از صفر آموزش می‌بینند؛ مسئله هزینه و مقیاس است.", "همین درست است: هزینه پیش‌آموزش و تمرکز این درس بر کاربرد و قضاوت.", "هاگینگ‌فیس ابزار آموزش هم دارد؛ انتخاب این درس آموزشی است، نه محدودیت کتابخانه.", "خطاهای مدل آماده موضوع اصلی کپستون همین فاز است؛ آماده بودن یعنی بی‌خطا بودن نیست."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-27-B', 2, 1, 'خواندن خروجی NER', 'تشخیص موجودیت فقط نام‌های خاص را می‌گیرد؛ در این جمله دو نام خاص هست، یکی آدم و یکی جا، و فعل و حرف اضافه موجودیت نیستند. جمع‌بندی: این سؤال مفهوم «خروجی درست NER» را تثبیت کرد: فقط نام‌های خاص، با نوع درست.', '["برچسب برای همه یعنی هیچ تمایزی نیست؛ بیشتر جمله موجودیت نیست.", "همین درست است: دو موجودیت با دو نوع درست.", "«درس» و «می‌خواند» اسم خاص نیستند و برچسب سازمان و شخص گرفتنشان خطاست.", "فعل جمله رویداد است، نه موجودیت نام‌دار."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-27-B', 3, 1, 'اطمینان برچسب', 'خط‌لوله کنار هر برچسب درجه باور خودش را هم می‌دهد؛ خواندن نقادانه یعنی استفاده از همان درجه، نه باور یکسان به همه برچسب‌ها. جمع‌بندی: این سؤال مفهوم «نمره اطمینان» را تثبیت کرد: اطمینان پایین، پرچم بررسی است نه حذف و نه باور کور.', '["باور یکسان یعنی دور ریختن اطلاعاتی که مدل خودش داده است.", "همین درست است: اطمینان پایین یعنی بررسی انسانی.", "۰٫۹۹ مطمئن‌ترین خروجی است؛ دور انداختنش وارونه خواندن نمره است.", "یک برچسب مشکوک یعنی بررسی همان یک مورد، نه حذف کل جمله."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-27-B', 4, 1, 'حد پاسخ استخراجی', 'مدل استخراجی برای پیدا کردن بازه ساخته شده است و «نیست» گفتن انتخاب پیش‌فرضش نیست؛ سنجیدن جواب با متن، وظیفه خواننده است و یکی از دسته‌های خطای کپستون همین است. جمع‌بندی: این سؤال مفهوم «حد پاسخ استخراجی» را تثبیت کرد: نبود جواب در متن، ممکن است باز هم بازه‌ای بسازد.', '["«نیست» گفتن مطمئن رفتار تضمین‌شده این مدل‌ها نیست و نباید رویش حساب کرد.", "همین درست است: بازه اجباری یعنی خطر جواب ساختگی از دل متن.", "مدل با متن داده‌شده فقط می‌خواند؛ پاک کردنی در کار نیست.", "خط‌لوله آفلاین روی همان متن کار می‌کند؛ اتصالی به اینترنت در کار نیست."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-27-B', 5, 1, 'دسته‌بندی خطای موجودیت', 'در این درس خطاهای مدل آماده دسته‌بندی می‌شوند: خطای مرز (کجا شروع و تمام شدن موجودیت)، خطای نوع برچسب (آدم، سازمان یا جا بودن) و در پاسخ پرسش، جواب بیرون از متن. این‌جا جای موجودیت درست پیدا شده و نوعش غلط است. جمع‌بندی: این سؤال مفهوم «دسته‌بندی خطا» را تثبیت کرد: مرز موجودیت، نوع برچسب و جواب بیرون از متن، سه دسته جدا.', '["مرز درست است؛ شروع و پایان موجودیت همان است که باید باشد.", "همین درست است: جای موجودیت درست و نوعش غلط، یعنی خطای نوع برچسب.", "جواب بیرون از متن مال پاسخ پرسش استخراجی است، نه برچسب موجودیت.", "توکنایزر متن را درست شکسته است؛ خطا در برچسب مدل است."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
insert into public.quiz_answer_keys (quiz_code, question_index, correct_option, concept_tag, teacher_note, explanations) values ('quiz-27-B', 6, 1, 'میانگین دروازه فاز ۸', 'دروازه روی میانگین نمره‌های چهار آزمون نمره‌دار این بخش سنجیده می‌شود، نه روی تک‌تک نمره‌ها؛ میانگین دقیقاً ۶۰ می‌شود و قاعده «از ۶۰ به بالا» خود ۶۰ را هم قبول می‌داند. جمع‌بندی: این سؤال مفهوم «میانگین دروازه فاز ۸» را تثبیت کرد: میانگین چهار آزمون درس‌های ب، با مرز قبول دقیقاً ۶۰.', '["نمره پایین تنها با میانگین سنجیده می‌شود و میانگین این‌جا دقیقاً روی مرز قبول است.", "همین درست است: میانگین ۶۰، روی آستانه قبول.", "«از ۶۰ به بالا» خود ۶۰ را هم شامل می‌شود؛ بالای صرف لازم نیست.", "شرط تک‌تک بالای ۶۰ در قاعده نیست؛ قاعده، میانگین چهار آزمون و تلاش شدن همه آن‌هاست."]'::jsonb) on conflict (quiz_code, question_index) do nothing;
